// ---- sky dome (vertical gradient) ----
const skyMat = new THREE.ShaderMaterial({
  side: THREE.BackSide, depthWrite: false,
  uniforms: {
    topColor: { value: new THREE.Color(0x428ac7) },
    bottomColor: { value: new THREE.Color(0xb4cee0) },
    offset: { value: 60 }, exponent: { value: 0.8 },
    sunDir: { value: new THREE.Vector3(0, 1, 0) },
    sunColor: { value: new THREE.Color(0xffe6b0) },
    sunGlow: { value: 1 },
  },
  vertexShader: `varying vec3 vWorldPosition;
    void main(){ vec4 wp = modelMatrix * vec4(position,1.0); vWorldPosition = wp.xyz;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
  fragmentShader: `uniform vec3 topColor; uniform vec3 bottomColor; uniform float offset; uniform float exponent;
    uniform vec3 sunDir; uniform vec3 sunColor; uniform float sunGlow;
    varying vec3 vWorldPosition;
    void main(){
      vec3 dir = normalize(vWorldPosition - cameraPosition);
      float h = dir.y;
      vec3 col = mix(bottomColor, topColor, pow(max(h,0.0), exponent));
      float sd = max(dot(dir, sunDir), 0.0);
      col += sunColor * pow(sd, 900.0) * 3.2 * sunGlow;   // sun disc
      col += sunColor * pow(sd, 24.0) * 0.32 * sunGlow;   // wide halo
      col += sunColor * pow(sd, 5.0) * 0.10 * sunGlow;    // atmospheric bloom
      gl_FragColor = vec4(col, 1.0); }`,
});
const sky = new THREE.Mesh(new THREE.SphereGeometry(600, 32, 16), skyMat);
scene.add(sky);

// ---- stars (fade in at night) ----
const starGeo = new THREE.BufferGeometry();
const starPos = new Float32Array(700 * 3);
for (let i = 0; i < 700; i++) {
  const r = 460, th = Math.random() * Math.PI * 2, ph = Math.acos(Math.random() * 0.9);
  starPos[i*3] = Math.sin(ph)*Math.cos(th)*r; starPos[i*3+1] = Math.abs(Math.cos(ph))*r*0.6 + 40; starPos[i*3+2] = Math.sin(ph)*Math.sin(th)*r;
}
starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
const starMat = new THREE.PointsMaterial({ color: 0xdfe7ff, size: 1.8, transparent: true, opacity: 0, depthWrite: false });
const stars = new THREE.Points(starGeo, starMat);
scene.add(stars);

// ---- procedural canvas textures (high-quality detail without external assets) ----
function makeTexture(size, fn, repeatX = 1, repeatY = 1) {
  const c = document.createElement('canvas'); c.width = c.height = size;
  const ctx = c.getContext('2d');
  const img = ctx.createImageData(size, size);
  const d = img.data;
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const rgb = fn(x / size, y / size);
      const i = (y * size + x) * 4;
      d[i] = rgb[0]; d[i + 1] = rgb[1]; d[i + 2] = rgb[2]; d[i + 3] = 255;
    }
  }
  ctx.putImageData(img, 0, 0);
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(repeatX, repeatY);
  tex.anisotropy = 8;
  return tex;
}
// soft radial glow (halos, fog banks, motes, god lights)
function makeGlowTexture(size = 128) {
  const c = document.createElement('canvas'); c.width = c.height = size;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  g.addColorStop(0, 'rgba(255,255,255,1)');
  g.addColorStop(0.22, 'rgba(255,255,255,0.55)');
  g.addColorStop(0.55, 'rgba(255,255,255,0.15)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g; ctx.fillRect(0, 0, size, size);
  return new THREE.CanvasTexture(c);
}
// height function -> tangent-space normal map (smooth water/ground relief)
function makeNormalMap(size, hFn, repeatX = 1, repeatY = 1, strength = 2.2) {
  const c = document.createElement('canvas'); c.width = c.height = size;
  const ctx = c.getContext('2d');
  const img = ctx.createImageData(size, size);
  const d = img.data;
  const e = 1 / size;
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const u = x / size, v = y / size;
      const hx = hFn(u + e, v) - hFn(u - e, v);
      const hy = hFn(u, v + e) - hFn(u, v - e);
      let nx = -hx * strength, ny = -hy * strength, nz = 1;
      const len = Math.hypot(nx, ny, nz);
      const i = (y * size + x) * 4;
      d[i] = (nx / len * 0.5 + 0.5) * 255;
      d[i + 1] = (ny / len * 0.5 + 0.5) * 255;
      d[i + 2] = (nz / len * 0.5 + 0.5) * 255;
      d[i + 3] = 255;
    }
  }
  ctx.putImageData(img, 0, 0);
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(repeatX, repeatY);
  return tex;
}
const TEX = {};
TEX.glow = makeGlowTexture();
// ground detail: neutral grayscale so it multiplies the biome vertex colors (seamless via world UVs)
TEX.ground = makeTexture(256, (u, v) => {
  const n = fbm(u * 6, v * 6, 101, 5);
  const m = fbm(u * 34, v * 34, 202, 3);
  const g = clamp(0.72 + n * 0.3 + m * 0.18, 0, 1) * 255;
  return [g, g, g];
});
// bark: vertical streaks
TEX.bark = makeTexture(128, (u, v) => {
  const streak = fbm(u * 20, v * 3.5, 303, 3);
  const base = 0.5 + streak * 0.55;
  return [clamp(84 * base, 0, 255), clamp(58 * base, 0, 255), clamp(36 * base, 0, 255)];
}, 2, 5);
// foliage: mottled green
TEX.leaf = makeTexture(128, (u, v) => {
  const n = fbm(u * 11, v * 11, 404, 4);
  const m = fbm(u * 32, v * 32, 505, 3);
  const g = 0.5 + n * 0.55 + m * 0.28;
  return [clamp(79 * g, 0, 255), clamp(108 * g, 0, 255), clamp(56 * g, 0, 255)];
}, 2, 2);
// pine needles: darker, blue-green
TEX.pine = makeTexture(128, (u, v) => {
  const n = fbm(u * 13, v * 13, 511, 4);
  const m = fbm(u * 30, v * 30, 512, 3);
  const g = 0.5 + n * 0.5 + m * 0.24;
  return [clamp(52 * g, 0, 255), clamp(77 * g, 0, 255), clamp(63 * g, 0, 255)];
}, 2, 2);
// cactus skin: green with pale spine speckles
TEX.cactus = makeTexture(128, (u, v) => {
  const n = fbm(u * 10, v * 10, 611, 4);
  const dot = fbm(u * 26, v * 26, 612, 3) > 0.72 ? 1.35 : 1;
  const g = (0.62 + n * 0.4) * dot;
  return [clamp(52 * g, 0, 255), clamp(128 * g, 0, 255), clamp(58 * g, 0, 255)];
}, 1, 1);
// rock: grey with cracks
TEX.rock = makeTexture(128, (u, v) => {
  const n = fbm(u * 13, v * 13, 606, 4);
  const crack = Math.abs(fbm(u * 24, v * 24, 707, 3) - 0.5) < 0.045 ? 0.62 : 1;
  const g = (0.62 + n * 0.5) * crack;
  return [clamp(126 * g, 0, 255), clamp(122 * g, 0, 255), clamp(114 * g, 0, 255)];
}, 2, 2);
// gold: subtle metallic variation for Tom Pearl
TEX.gold = makeTexture(128, (u, v) => {
  const n = fbm(u * 15, v * 15, 808, 3);
  const g = 0.82 + n * 0.34;
  return [clamp(255 * g, 0, 255), clamp(206 * g, 0, 255), clamp(112 * g, 0, 255)];
}, 1, 1);
// water ripple normals (animated by scrolling the offset each frame)
TEX.waterN = makeNormalMap(128, (u, v) => fbm(u * 7, v * 7, 909, 4) * 0.72 + fbm(u * 19, v * 19, 910, 3) * 0.28, 40, 40, 2.6);

// ---- smooth organic blob: noise-displaced sphere with smooth normals ----
function makeBlobGeometry(seed, squash = 0.92) {
  const geo = new THREE.SphereGeometry(1, 12, 8);
  const pos = geo.attributes.position;
  const v = new THREE.Vector3();
  for (let i = 0; i < pos.count; i++) {
    v.fromBufferAttribute(pos, i);      const n = fbm(v.x * 1.15 + seed * 3.1, v.z * 1.15 + v.y * 0.75, seed * 7 + 3, 3);
    const s = 1 + (n - 0.5) * 0.6;
    pos.setXYZ(i, v.x * s, v.y * s * squash, v.z * s);
  }
  geo.computeVertexNormals();
  return geo;
}

// ---- shared geometry (smooth, curved) & materials (textured) ----
const GEOM = {
  trunk: new THREE.CylinderGeometry(0.34, 0.52, 1, 10, 2),
  leaf: makeBlobGeometry(1),
  leafB: makeBlobGeometry(2),
  leafC: makeBlobGeometry(3, 0.82),
  rock: makeBlobGeometry(4, 0.72),
  bush: makeBlobGeometry(5, 0.62),
  cone: new THREE.ConeGeometry(1, 1, 9, 2),
  cactusArm: new THREE.CylinderGeometry(0.17, 0.2, 1, 10, 2),
};
GEOM.leafVariants = [GEOM.leaf, GEOM.leafB, GEOM.leafC];
const SHARED_GEOMS = new Set([GEOM.trunk, GEOM.leaf, GEOM.leafB, GEOM.leafC, GEOM.rock, GEOM.bush, GEOM.cone, GEOM.cactusArm]);
const MAT = {
  trunk: new THREE.MeshStandardMaterial({ map: TEX.bark, bumpMap: TEX.bark, bumpScale: 0.05, roughness: 0.92, metalness: 0.02, color: 0xffffff }),
  foliage: new THREE.MeshStandardMaterial({ map: TEX.leaf, bumpMap: TEX.leaf, bumpScale: 0.04, roughness: 0.82, metalness: 0.0, emissive: 0x000000, emissiveIntensity: 0, color: 0xffffff }),
  foliageDark: new THREE.MeshStandardMaterial({ map: TEX.leaf, bumpMap: TEX.leaf, bumpScale: 0.04, roughness: 0.88, color: 0x86a886 }),
  pine: new THREE.MeshStandardMaterial({ map: TEX.pine, bumpMap: TEX.pine, bumpScale: 0.05, roughness: 0.9, color: 0xffffff }),
  cactus: new THREE.MeshStandardMaterial({ map: TEX.cactus, bumpMap: TEX.cactus, bumpScale: 0.04, roughness: 0.85, color: 0xffffff }),
  rock: new THREE.MeshStandardMaterial({ map: TEX.rock, bumpMap: TEX.rock, bumpScale: 0.12, roughness: 1.0, color: 0xffffff }),
  bush: new THREE.MeshStandardMaterial({ map: TEX.leaf, bumpMap: TEX.leaf, bumpScale: 0.04, roughness: 0.9, color: 0x7d9c74 }),
  fogBank: new THREE.SpriteMaterial({ map: TEX.glow, color: 0xc8d3da, transparent: true, opacity: 0.07, depthWrite: false, blending: THREE.AdditiveBlending }),
};

// ---- deterministic RNG per chunk ----
function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// ---- a single stylized tree (smooth, curved canopies) ----
// kind: 'broad' (round canopy) | 'pine' (stacked cones) | 'cactus'
function makeTree(rng, kind = 'broad') {
  const g = new THREE.Group();
  let hp = 8, radius = 0.55;
  if (kind === 'cactus') {
    const h = 2.4 + rng() * 1.8;
    const parts = [];
    const body = new THREE.CylinderGeometry(0.42, 0.5, h, 12, 4);
    body.translate(0, h / 2, 0); parts.push(body);
    const arms = 1 + Math.floor(rng() * 2);
    for (let i = 0; i < arms; i++) {
      const a = GEOM.cactusArm.clone();
      const ang = rng() * Math.PI * 2, ah = 0.8 + rng() * 0.9, up = 0.9 + rng() * 1.1;
      a.rotateZ(Math.PI / 2.6 * (rng() > 0.5 ? 1 : -1));
      a.rotateY(ang);
      a.translate(Math.cos(ang) * 0.62, up + ah * 0.4, Math.sin(ang) * 0.62);
      a.scale(1, ah, 1);
      parts.push(a);
    }
    const merged = mergeGeometries(parts, false);
    g.add(new THREE.Mesh(merged || parts[0], MAT.cactus));
    if (merged) for (const p of parts) p.dispose();
    hp = 10; radius = 0.62;
  } else if (kind === 'pine') {
    const h = 4 + rng() * 3.2;
    const trunk = new THREE.Mesh(GEOM.trunk, MAT.trunk);
    // The woody core ends inside the crown, never above its final tier.
    trunk.scale.set(0.55, h * .73, 0.55);
    trunk.position.y = h * .365;
    g.add(trunk);
    const tiers = 3 + Math.floor(rng() * 2);
    const parts = [];
    for (let i = 0; i < tiers; i++) {
      const f = i / tiers;
      const c = GEOM.cone.clone();
      const r = 1.7 * (1 - f * 0.62), ch = 1.9;
      c.scale(r, ch, r);
      c.translate(0, h * 0.32 + i * (h * 0.21), 0);
      parts.push(c);
    }
    const merged = mergeGeometries(parts, false);
    g.add(new THREE.Mesh(merged || parts[0], MAT.pine));
    if (merged) for (const p of parts) p.dispose();
    hp = 8; radius = 0.55;
  } else {
    const h = 3.2 + rng() * 3.4;
    const trunk = new THREE.Mesh(GEOM.trunk, MAT.trunk);
    trunk.scale.set(0.85 + rng() * 0.4, h, 0.85 + rng() * 0.4);
    trunk.position.y = h / 2;
    g.add(trunk);
    // full, rounded canopy: many smooth leaf blobs merged into one mesh
    const clusters = 4 + Math.floor(rng() * 3); // canonical gameplay RNG consumption, independent of LOD
    const canopyR = 1.7 + rng() * 1.1;
    const parts = [];
    for (let i = 0; i < clusters; i++) {
      const leafGeo = GEOM.leafVariants[Math.floor(rng() * GEOM.leafVariants.length)].clone();
      const s = 1.0 + rng() * 1.1;
      const ang = rng() * Math.PI * 2;
      const rad = rng() * canopyR;
      const m = new THREE.Matrix4().compose(
        new THREE.Vector3(Math.cos(ang) * rad, h * 0.72 + (rng() - 0.15) * 2.4, Math.sin(ang) * rad),
        new THREE.Quaternion().setFromEuler(new THREE.Euler(rng(), rng() * 6, rng())),
        new THREE.Vector3(s, s, s)
      );
      leafGeo.applyMatrix4(m);
      parts.push(leafGeo);
    }
    const merged = mergeGeometries(parts, false);
    g.add(new THREE.Mesh(merged || parts[0], MAT.foliage));
    if (merged) for (const p of parts) p.dispose();
    hp = 8; radius = 0.55;
  }
  if (kind !== 'cactus') {
    const height = new THREE.Box3().setFromObject(g).getSize(new THREE.Vector3()).y;
    const model = ART.instance(kind === 'pine' ? 'pine' : height > 6 ? 'treeTall' : 'tree', height);
    if (model) {
      g.traverse(o => { if (o.geometry && !SHARED_GEOMS.has(o.geometry)) o.geometry.dispose(); });
      g.clear(); g.add(model);
    }
  }
  // Preserve harvest identity; imported geometries are library-owned.
  g.traverse((o) => { o.userData.noMerge = true; });
  return { group: g, radius, hp, kind };
}
function makeRock(rng) {
  const m = new THREE.Mesh(GEOM.rock, MAT.rock);
  const s = 0.5 + rng() * 1.3;
  m.scale.set(s, s * (0.6 + rng() * 0.6), s);
  m.rotation.set(rng(), rng() * 6, rng());
  m.position.y = s * 0.3;
  m.userData.noMerge = true;             // rocks are mineable, so keep them individual
  const model = ART.instance(s > 1 ? 'rockB' : 'rock', s * 1.15);
  if (model) { model.rotation.y = m.rotation.y; model.traverse(o => { o.userData.noMerge = true; }); }
  return { mesh: model || m, radius: s * 0.85, hp: 12 };
}
function makeBush(rng) {
  const g = new THREE.Group();
  const b = new THREE.Mesh(GEOM.bush, MAT.bush);
  const s = 0.5 + rng() * 0.7;
  b.scale.set(s, s * 0.75, s);
  b.position.y = s * 0.42;
  g.add(b);
  g.traverse((o) => { o.userData.noMerge = true; });   // bushes are harvestable
  return g;
}
// buried ore node (exposed when digging lowers the ground above it)
function makeOreNode(kind) {
  const g = new THREE.Group();
  const rock = new THREE.Mesh(GEOM.rock, MAT.rock);
  rock.scale.setScalar(0.8);
  g.add(rock);
  const oreMat = kind === 'gold'
    ? new THREE.MeshStandardMaterial({ color: 0xffd35c, emissive: 0xffb43a, emissiveIntensity: 1.1, roughness: 0.35, metalness: 0.6 })
    : new THREE.MeshStandardMaterial({ color: 0xcfd6dd, emissive: 0x6a90b8, emissiveIntensity: 0.7, roughness: 0.4, metalness: 0.7 });
  for (let i = 0; i < 5; i++) {
    const nug = new THREE.Mesh(new THREE.SphereGeometry(0.17, 10, 8), oreMat);
    const a = (i / 5) * Math.PI * 2;
    nug.position.set(Math.cos(a) * 0.55, (i % 2) * 0.42 - 0.1, Math.sin(a) * 0.55);
    g.add(nug);
  }
  g.userData.ownedMaterials=[oreMat];
  g.traverse((o) => { o.userData.noMerge = true; });
  return g;
}

// merge a chunk's static prop meshes into one mesh per material (fewer draw calls)
function mergeChunkProps(group, terrainMesh) {
  group.updateMatrixWorld(true);
  const buckets = new Map();
  const meshes = [];
  group.traverse((o) => {
    if (o.isMesh && o !== terrainMesh && !o.userData.noMerge) {
      meshes.push(o);
      const key = o.material.uuid;
      if (!buckets.has(key)) buckets.set(key, []);
      buckets.get(key).push(o);
    }
  });
  for (const list of buckets.values()) {
    if (list.length < 2) continue;
    const geos = list.map((m) => {
      const g = m.geometry.clone();
      g.applyMatrix4(m.matrixWorld);
      return g.index ? g.toNonIndexed() : g;
    });
    let merged = null;
    try { merged = mergeGeometries(geos, false); } catch (e) { merged = null; }
    for (const g of geos) g.dispose();
    if (!merged) continue;                      // merge failed: keep the originals
    const mesh = new THREE.Mesh(merged, list[0].material);
    mesh.castShadow = true; mesh.receiveShadow = true;
    group.add(mesh);
    for (const m of list) m.parent.remove(m);
  }
}

// ---- chunk generation ----
// Locally bundled Poly Haven CC0 materials; generated maps remain immediate fallbacks.
const materialLoader = new THREE.TextureLoader();
function loadLocalTexture(path, repeat, color = true) {
  const fallback = path.includes('normal') ? TEX.waterN : path.includes('bark') ? TEX.bark : path.includes('rock') ? TEX.rock : TEX.ground;
  const t = materialLoader.load(path, undefined, undefined, e => {
    console.warn('Local material unavailable, using procedural fallback:', path);
    if (fallback && fallback.image) { t.image = fallback.image; t.needsUpdate = true; }
  });
  t.wrapS = t.wrapT = THREE.RepeatWrapping; t.repeat.set(...repeat);
  t.colorSpace = color ? THREE.SRGBColorSpace : THREE.NoColorSpace;
  t.anisotropy = Math.min(8, renderer.capabilities.getMaxAnisotropy());
  return t;
}
TEX.wood = loadLocalTexture('./assets/textures/wood_planks_grey.jpg', [1, 1]);
TEX.woodNormal = loadLocalTexture('./assets/textures/wood_planks_grey-normal.jpg', [1, 1], false);
TEX.ground = loadLocalTexture('./assets/textures/forest_floor.jpg', [1, 1]);
TEX.groundNormal = loadLocalTexture('./assets/textures/forest_floor-normal.jpg', [1, 1], false);
TEX.bark = loadLocalTexture('./assets/textures/bark_brown_02.jpg', [1, 3]);
TEX.rock = loadLocalTexture('./assets/textures/rock_boulder_dry.jpg', [1, 1]);
MAT.trunk.map = TEX.bark; MAT.trunk.bumpMap = null;
MAT.trunk.normalMap = loadLocalTexture('./assets/textures/bark_brown_02-normal.jpg', [1, 3], false);
MAT.rock.map = TEX.rock; MAT.rock.bumpMap = null;
MAT.rock.normalMap = loadLocalTexture('./assets/textures/rock_boulder_dry-normal.jpg', [1, 1], false);
// Ground albedo is desaturated in shader before multiplying biome colors; snow/sand stay coherent.
function generateChunk(cx, cz) {
  const CS = CFG.chunkSize;
  const seg = Q.terrainSeg;
  const geo = new THREE.PlaneGeometry(CS, CS, seg, seg);
  geo.rotateX(-Math.PI / 2);
  geo.translate(CS / 2, 0, CS / 2);           // vertices now span [0..CS] in local x/z
  const pos = geo.attributes.position;
  const uv = geo.attributes.uv;
  const colors = new Float32Array(pos.count * 3);
  const scratch = new THREE.Color();
  const ox = cx * CS, oz = cz * CS;
  for (let i = 0; i < pos.count; i++) {
    const wx = ox + pos.getX(i), wz = oz + pos.getZ(i);
    const h = terrainHeight(wx, wz);          // edited surface; props use undug deterministic anchors
    pos.setY(i, h);
    uv.setXY(i, wx * 0.35, wz * 0.35);      // world-based tiling (seamless across chunks)
    const c = biomeTint(wx, wz, h, scratch);
    if(digOffset(wx,wz)<-.03)c.lerp(BIOME.dirt,.65);
    colors[i*3] = c.r; colors[i*3+1] = c.g; colors[i*3+2] = c.b;
  }
  geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  uv.needsUpdate = true;
  geo.computeVertexNormals();
  const normals=geo.attributes.normal;
  for(let i=0;i<pos.count;i++){const x=ox+pos.getX(i),z=oz+pos.getZ(i),dx=(terrainHeight(x+.15,z)-terrainHeight(x-.15,z))/.3,dz=(terrainHeight(x,z+.15)-terrainHeight(x,z-.15))/.3,len=Math.hypot(dx,1,dz);normals.setXYZ(i,-dx/len,1/len,-dz/len);}
  const terrainMat = new THREE.MeshStandardMaterial({ vertexColors: true, map: TEX.ground, normalMap: TEX.groundNormal, normalScale: new THREE.Vector2(0.65, 0.65), roughness: 0.96, metalness: 0.0 });
  terrainMat.onBeforeCompile = shader => {
    shader.fragmentShader = shader.fragmentShader.replace('#include <map_fragment>', '#include <map_fragment>\n float soilLum = dot(sampledDiffuseColor.rgb, vec3(0.2126,0.7152,0.0722));\n diffuseColor.rgb = diffuseColor.rgb / max(sampledDiffuseColor.rgb, vec3(0.001)) * mix(vec3(0.38), vec3(0.98), clamp(soilLum * 2.8, 0.0, 1.0));');
  };
  const mesh = new THREE.Mesh(geo, terrainMat);
  mesh.position.set(ox, 0, oz);
  mesh.receiveShadow = true; mesh.castShadow = true;

  const group = new THREE.Group();
  group.add(mesh);
  const colliders = [];
  const harvest = [];

  // water surface: only where the undug land is below the water line,
  // so dug craters on dry land never flood
  const waterParts = [];
  for (let ix = 0; ix < CS; ix++) {
    for (let iz = 0; iz < CS; iz++) {
      const bh = baseHeight(ox + ix + 0.5, oz + iz + 0.5);
      if (bh < CFG.waterLevel - 0.25) {
        const q = new THREE.PlaneGeometry(1, 1);
        q.rotateX(-Math.PI / 2);
        q.translate(ix + 0.5, CFG.waterLevel, iz + 0.5);
        waterParts.push(q);
      }
    }
  }
  if (waterParts.length) {
    const wgeo = mergeGeometries(waterParts, false);
    if (wgeo) { for (const q of waterParts) q.dispose(); }
    const wm = new THREE.Mesh(wgeo || waterParts[0], waterMat);
    wm.position.set(ox, 0, oz);
    wm.userData.noMerge = true;
    wm.renderOrder = 1;
    group.add(wm);
  }

  // scatter props deterministically (varies by biome)
  const rng = mulberry32((cx * 73856093) ^ (cz * 19349663) ^ CFG.seed);
  const midH = baseHeight(ox + CS / 2, oz + CS / 2);
  const chunkBiome = biomeAt(ox + CS / 2, oz + CS / 2, midH);
  const treeBase = chunkBiome === 'forest' ? 6 : chunkBiome === 'snow' ? 3
    : chunkBiome === 'plains' ? 2 : chunkBiome === 'desert' ? 2 : 1;
  // Gameplay scattering is canonical (the original High layout), never a graphics setting.
  const treeCount = Math.max(0, treeBase - 1 + Math.floor(rng() * 3));
  for (let i = 0; i < treeCount; i++) {
    const lx = rng() * CS, lz = rng() * CS;
    const wx = ox + lx, wz = oz + lz;
    const h = baseHeight(wx, wz);
    if (h < CFG.waterLevel + 0.5) continue;      // no trees underwater
    if (h > 16.5) continue;                      // above the tree line
    const b = biomeAt(wx, wz, h);
    const kind = b === 'desert' ? 'cactus' : b === 'snow' ? 'pine' : (rng() < 0.22 ? 'pine' : 'broad');
    const t = makeTree(rng, kind);
    const treeRotation = rng() * Math.PI * 2; // consume RNG even for removed trees
    if (world.chopped.has(hkey(wx, wz))) continue;    // stays gone after being chopped
    t.group.position.set(wx, h - 0.1, wz);
    t.group.rotation.y = treeRotation;
    group.add(t.group);
    colliders.push({ x: wx, z: wz, r: t.radius });
    harvest.push({ x: wx, z: wz, r: Math.max(1.35, t.radius + 1.0), hp: t.hp, maxHp: t.hp, type: 'tree', group: t.group, shake: 0, dead: false });
  }
  const rockMul = chunkBiome === 'mountain' ? 2.1 : chunkBiome === 'desert' ? 1.4 : 1;
  const rockCount = Math.max(1, Math.round((1 + Math.floor(rng() * 3)) * rockMul));
  for (let i = 0; i < rockCount; i++) {
    const lx = rng() * CS, lz = rng() * CS;
    const wx = ox + lx, wz = oz + lz;
    const h = baseHeight(wx, wz);
    if (h < CFG.waterLevel + 0.2) continue;
    const r = makeRock(rng);
    if (world.chopped.has(hkey(wx, wz))) continue;
    r.mesh.position.set(wx, h - 0.15, wz);
    group.add(r.mesh);
    colliders.push({ x: wx, z: wz, r: r.radius });
    harvest.push({ x: wx, z: wz, r: Math.max(1.1, r.radius + 0.8), hp: r.hp, maxHp: r.hp, type: 'rock', group: r.mesh, shake: 0, dead: false });
  }
  const bushCount = Math.max(0, 1 + Math.floor(rng() * 3));
  for (let i = 0; i < bushCount; i++) {
    const lx = rng() * CS, lz = rng() * CS;
    const wx = ox + lx, wz = oz + lz;
    const h = baseHeight(wx, wz);
    if (h < CFG.waterLevel + 0.3 || h > 14) continue;
    const bush = makeBush(rng);
    const bushRotation = rng() * Math.PI * 2;
    if (world.chopped.has(hkey(wx, wz))) continue;
    bush.position.set(wx, h, wz);
    bush.rotation.y = bushRotation;
    group.add(bush);
    harvest.push({ x: wx, z: wz, r: 1.2, hp: 2, maxHp: 2, type: 'bush', group: bush, shake: 0, dead: false });
  }

  // buried ore veins (exposed by digging the ground down to them)
  const oreCount = 1 + Math.floor(rng() * 3);
  for (let i = 0; i < oreCount; i++) {
    const lx = rng() * CS, lz = rng() * CS;
    const wx = ox + lx, wz = oz + lz;
    const baseH = terrainHeight(wx, wz) - digOffset(wx, wz);   // undug surface
    if (baseH < CFG.waterLevel + 0.5) continue;
    const key = hkey(wx, wz);
    const ny = baseH - (CFG.terrainVersion===2 ? 1.2 + rng()*.9 : 2.5 + rng()*4.5);
    const kind = rng() < 0.72 ? 'iron' : 'gold';
    if (world.oreTaken.has(key)) continue;
    const node = makeOreNode(kind);
    node.position.set(wx, ny, wz);
    const hidden = !world.oreShown.has(key);
    node.visible = !hidden;
    group.add(node);
    harvest.push({ x: wx, z: wz, y: ny, r: 1.3, hp: 15, maxHp: 15, type: 'ore', oreKind: kind, hidden, group: node, shake: 0, dead: false });
  }

  // Presentation gets an independent stream and stable maximum set; quality only hides detail.
  const decoration = new THREE.Group(); group.add(decoration);
  const detailRng = mulberry32((cx * 83492791) ^ (cz * 297121507) ^ CFG.seed ^ 0xdec0);
  for (let i = 0; i < 8; i++) {
    const wx = ox + detailRng()*CS, wz = oz + detailRng()*CS, y = baseHeight(wx,wz);
    if (y < CFG.waterLevel+.6 || y > 15) continue;
    const biome = biomeAt(wx,wz,y);
    if (biome === 'snow' || biome === 'desert') continue;
    const pebble = new THREE.Mesh(GEOM.rock, MAT.rock);
    pebble.position.set(wx,y+.04,wz);pebble.scale.set(.13+detailRng()*.12,.08,.18);decoration.add(pebble);
    if (i === 0 && biome === 'forest') {
      const length = 2.4 + detailRng()*2, angle = detailRng()*Math.PI;
      const log = ART.instance('log', .55) || new THREE.Mesh(GEOM.trunk, MAT.trunk);
      log.position.set(wx,y+.05,wz); log.rotation.y=angle;
      log.scale.z *= length/2; decoration.add(log);
    }
  }
  // glowing fog banks drifting through the low valleys
  const fogDecoration = new THREE.Group(); group.add(fogDecoration);
  {
    const bankCount = detailRng() < .825 ? 1 + Math.floor(detailRng() * 2) : 0;
    for (let i = 0; i < bankCount; i++) {
      const lx = rng() * CS, lz = rng() * CS;
      const wx = ox + lx, wz = oz + lz;
      const h = baseHeight(wx, wz);
      if (h > CFG.waterLevel + 3.2) continue;
      const spr = new THREE.Sprite(MAT.fogBank);
      const s = 13 + rng() * 12;
      spr.scale.set(s, s * 0.32, 1);
      spr.position.set(wx, h + 1.7 + rng() * 2.4, wz);
      fogDecoration.add(spr);
    }
  }
  // No merging across independently culled decorative groups.
  for (const h of harvest) {
    h.id = `${CFG.seed}:${cx},${cz}:${h.type}:${hkey(h.x,h.z)}`;
    const saved = world.harvestState.get(h.id);
    if (saved) { h.hp = saved.hp; h.dead = !!saved.dead; h.hidden = h.type==='ore'&&world.oreShown.has(hkey(h.x,h.z))?false:saved.hidden ?? h.hidden; h.group.visible = !h.dead && !h.hidden; }
  }
  const data = { cx, cz, group, colliders, harvest, decoration, fogDecoration, terrainMat, terrainMesh: mesh };
  applyChunkVisuals(data);
  return data;
}

function applyChunkVisuals(chunk) {
  chunk.decoration.children.forEach((o,i)=>{o.visible=i<Math.round(5*Q.foliage);});
  chunk.fogDecoration.visible=Q.fogBanks>0;
  chunk.fogDecoration.children.forEach((o,i)=>{o.visible=i<Math.ceil(Q.fogBanks);});
}

// ---- streaming ----
function loadChunk(cx, cz) {
  const key = cx + ',' + cz;
  if (world.chunks.has(key)) return;
  const data = generateChunk(cx, cz);
  scene.add(data.group);
  world.chunks.set(key, data);
  rebuildColliders();
}
function unloadChunk(key) {
  const data = world.chunks.get(key);
  if (!data) return;
  for (const h of data.harvest) world.harvestState.set(h.id,{hp:h.hp,dead:h.dead,hidden:h.hidden});
  scene.remove(data.group);
  data.group.traverse((o) => { if (o.geometry && !SHARED_GEOMS.has(o.geometry)) o.geometry.dispose();for(const m of o.userData.ownedMaterials||[])m.dispose(); });
  data.terrainMat.dispose();
  world.chunks.delete(key);
  rebuildColliders();
}
function rebuildColliders() {
  world.colliders.length = 0;
  world.harvestables.length = 0;
  for (const d of world.chunks.values()) {
    world.colliders.push(...d.colliders.filter(c => !d.harvest.some(h => h.dead && Math.abs(h.x-c.x)<.01 && Math.abs(h.z-c.z)<.01)));
    world.harvestables.push(...d.harvest);
  }
  for (const c of world.caves) {
    world.colliders.push(...c.colliders);
    world.harvestables.push(...c.harvest);
  }
}
// Terrain-only updates: never regenerate props, harvest HP, identities or colliders.
function remeshChunk(cx,cz){
  const chunk=world.chunks.get(cx+','+cz);if(!chunk)return;
  const geo=chunk.terrainMesh.geometry,p=geo.attributes.position,c=geo.attributes.color,n=geo.attributes.normal,scratch=new THREE.Color();
  for(let i=0;i<p.count;i++){
    const x=cx*CFG.chunkSize+p.getX(i),z=cz*CFG.chunkSize+p.getZ(i),h=terrainHeight(x,z);
    p.setY(i,h);biomeTint(x,z,h,scratch);if(digOffset(x,z)<-.03)scratch.lerp(BIOME.dirt,.65);
    c.setXYZ(i,scratch.r,scratch.g,scratch.b);
    const dx=(terrainHeight(x+.15,z)-terrainHeight(x-.15,z))/.3,dz=(terrainHeight(x,z+.15)-terrainHeight(x,z-.15))/.3,len=Math.hypot(dx,1,dz);
    n.setXYZ(i,-dx/len,1/len,-dz/len);
  }
  p.needsUpdate=c.needsUpdate=n.needsUpdate=true;geo.computeBoundingBox();geo.computeBoundingSphere();
}
function remeshNear(x, z, r) {
  const CS = CFG.chunkSize;
  const x0 = Math.floor((x - r) / CS), x1 = Math.floor((x + r) / CS);
  const z0 = Math.floor((z - r) / CS), z1 = Math.floor((z + r) / CS);
  for (let cx = x0; cx <= x1; cx++)
    for (let cz = z0; cz <= z1; cz++) remeshChunk(cx, cz);
}
function updateChunks(px, pz) {
  const CS = CFG.chunkSize, R = CFG.viewRadius;
  const pcx = Math.floor(px / CS), pcz = Math.floor(pz / CS);
  // load
  for (let dz = -R; dz <= R; dz++)
    for (let dx = -R; dx <= R; dx++)
      loadChunk(pcx + dx, pcz + dz);
  // unload distant
  for (const key of Array.from(world.chunks.keys())) {
    const [cx, cz] = key.split(',').map(Number);
    if (Math.abs(cx - pcx) > R + 1 || Math.abs(cz - pcz) > R + 1) unloadChunk(key);
  }
}

// ---- water material (per-chunk water quads sit only over natural lowlands) ----
const waterMat = new THREE.MeshStandardMaterial({
  color: 0x1a5c66, transparent: true, opacity: 0.72, roughness: 0.12, metalness: 0.55,
  emissive: 0x0a3038, emissiveIntensity: 0.55, side: THREE.DoubleSide,
  normalMap: TEX.waterN, normalScale: new THREE.Vector2(0.42, 0.42),
});

// ---- ambient drifting motes (atmosphere; count set by graphics quality) ----
const MOTES_MAX = 480;
const moteGeo = new THREE.BufferGeometry();
const motePos = new Float32Array(MOTES_MAX * 3);
const moteSeed = new Float32Array(MOTES_MAX);
for (let i = 0; i < MOTES_MAX; i++) {
  motePos[i*3] = (Math.random() - 0.5) * 60;
  motePos[i*3+1] = Math.random() * 20 - 3;
  motePos[i*3+2] = (Math.random() - 0.5) * 60;
  moteSeed[i] = Math.random() * 100;
}
moteGeo.setAttribute('position', new THREE.BufferAttribute(motePos, 3));
const moteMat = new THREE.PointsMaterial({ map: TEX.glow, color: 0xe1d4b8, size: 0.16, transparent: true, opacity: 0.45, depthWrite: false, blending: THREE.AdditiveBlending });
const motes = new THREE.Points(moteGeo, moteMat);
motes.frustumCulled = false;
scene.add(motes);
function updateMotes(dt) {
  const visible = Math.min(Q.motes, MOTES_MAX);
  moteGeo.setDrawRange(0, visible);
  if (!visible) return;
  const arr = moteGeo.attributes.position.array;
  const cx = camera.position.x, cy = camera.position.y, cz = camera.position.z;
  for (let i = 0; i < visible; i++) {
    arr[i*3]   += Math.sin(state.time * 0.35 + moteSeed[i]) * dt * 0.5;
    arr[i*3+1] += (0.12 + Math.sin(state.time * 0.22 + moteSeed[i] * 1.7) * 0.1) * dt;
    arr[i*3+2] += Math.cos(state.time * 0.3 + moteSeed[i] * 0.7) * dt * 0.5;
    if (arr[i*3] > cx + 30) arr[i*3] -= 60; else if (arr[i*3] < cx - 30) arr[i*3] += 60;
    if (arr[i*3+1] > cy + 10) arr[i*3+1] -= 20; else if (arr[i*3+1] < cy - 10) arr[i*3+1] += 20;
    if (arr[i*3+2] > cz + 30) arr[i*3+2] -= 60; else if (arr[i*3+2] < cz - 30) arr[i*3+2] += 60;
  }
  moteGeo.attributes.position.needsUpdate = true;
}

// =====================================================================
// S2 · INPUT + FIRST-PERSON PLAYER CONTROLLER
// =====================================================================
const input = {
  keys: new Set(),
  forward: false, back: false, left: false, right: false,
  sprint: false, jump: false,
  pointerLocked: false, dragging: false, mode: 'cursor', pending: false,
  lastX: 0, lastY: 0, requestId: 0, requestedAt: 0, unlockedAt: -1000,
};
const player = {
  pos: new THREE.Vector3(0, 0, 0),   // feet position
  vel: new THREE.Vector3(),
  yaw: 0, pitch: -0.08,
  onGround: false,
  bob: 0, radius: CFG.playerRadius,
};
const EYE = CFG.playerHeight;
// Previously 6 moving / 11 resting, no explicit delay. Brief 0.45s recovery gate, +27% regen.
const STAMINA={delay:.45,sprintDrain:15,walkRegen:7.6,restRegen:14};

function refreshInput() {
  const k = input.keys;
  input.forward = k.has('KeyW') || k.has('ArrowUp');
  input.back    = k.has('KeyS') || k.has('ArrowDown');
  input.left    = k.has('KeyA') || k.has('ArrowLeft');
  input.right   = k.has('KeyD') || k.has('ArrowRight');
  input.sprint  = k.has('ShiftLeft') || k.has('ShiftRight');
  input.jump    = k.has('Space');
}

function resolveCollision(pos, radius) {
  // push out of prop colliders (tree trunks, rocks) in XZ
  for (const c of world.colliders) {
    const dx = pos.x - c.x, dz = pos.z - c.z;
    const rr = c.r + radius;
    const d2 = dx * dx + dz * dz;
    if (c.minY !== undefined && (pos.y > c.maxY || pos.y + EYE < c.minY)) continue;
    if(c.minY===undefined&&pos.y+EYE<terrainHeight(c.x,c.z)-1)continue;
    if (d2 < rr * rr) {
      if (d2 > 1e-6) {
        const d = Math.sqrt(d2);
        const push = (rr - d);
        pos.x += (dx / d) * push;
        pos.z += (dz / d) * push;
      } else {
        // exactly centered: push straight out so the player can't get stuck
        pos.x += rr;
      }
    }
  }
}

function updatePlayer(dt) {
  if (!state.started || state.dead || state.paused) return;

  // --- look is applied via player.yaw / player.pitch (set by mouse) ---
  const move = new THREE.Vector3();
  const forward = new THREE.Vector3(-Math.sin(player.yaw), 0, -Math.cos(player.yaw));
  const right = new THREE.Vector3(Math.cos(player.yaw), 0, -Math.sin(player.yaw));
  if (input.forward) move.add(forward);
  if (input.back) move.sub(forward);
  if (input.right) move.add(right);
  if (input.left) move.sub(right);
  const moving = move.lengthSq() > 0.001;
  if (moving) move.normalize();

  // --- swimming (body under the water surface) ---
  const swimming = underwaterAt(player.pos.x, player.pos.y + 0.6, player.pos.z);

  // --- sprint + stamina ---
  const wantSprint = input.sprint && moving && state.stamina > 1;
  const speed = (wantSprint ? CFG.sprintSpeed : CFG.walkSpeed) * (swimming ? 0.62 : 1);
  state.staminaWait=Math.max(0,(state.staminaWait||0)-dt);
  if (wantSprint) {state.stamina=clamp(state.stamina-dt*STAMINA.sprintDrain,0,100);state.staminaWait=STAMINA.delay;}
  else if(!state.staminaWait)state.stamina=clamp(state.stamina+dt*(moving?STAMINA.walkRegen:STAMINA.restRegen),0,100);

  // --- horizontal velocity (snappy accel) ---
  const accel = player.onGround ? 12 : 5;
  player.vel.x = lerp(player.vel.x, move.x * speed, clamp(accel * dt, 0, 1));
  player.vel.z = lerp(player.vel.z, move.z * speed, clamp(accel * dt, 0, 1));

  // --- jump / swim up + gravity ---
  if (swimming) {
    player.vel.y -= CFG.gravity * 0.22 * dt;
    player.vel.y *= Math.exp(-3 * dt);
    if (input.keys.has('ControlLeft') || input.keys.has('ControlRight')) player.vel.y -= 18 * dt;
    if (!input.jump && !input.keys.has('ControlLeft')) player.vel.y += (CFG.waterLevel - EYE * 0.7 - player.pos.y) * dt * 4;
    if (input.jump) player.vel.y = Math.min(player.vel.y + 26 * dt, 4.4);
    player.onGround = false;
  } else {
    if (input.jump && player.onGround) {
      player.vel.y = CFG.jumpSpeed;
      player.onGround = false;
      AudioFX.play('jump');
    }
    player.vel.y -= CFG.gravity * dt;
  }

  // --- integrate + terrain follow ---
  player.pos.x += player.vel.x * dt;
  player.pos.z += player.vel.z * dt;
  player.pos.y += player.vel.y * dt;

  const ground = groundHeightAt(player.pos.x, player.pos.z);
  if (player.pos.y <= ground) {
    player.pos.y = ground;
    if (player.vel.y < -14) AudioFX.play('land');
    player.vel.y = 0;
    player.onGround = true;
  } else {
    player.onGround = false;
  }

  // --- prop collision (push out of trunks/rocks) ---
  resolveCollision(player.pos, player.radius);
  if (typeof resolveBuildCollision === 'function')  resolveBuildCollision(player.pos, player.radius);
  const correctedGround = groundHeightAt(player.pos.x, player.pos.z);
  if (player.pos.y < correctedGround) { player.pos.y = correctedGround; player.vel.y = Math.max(0, player.vel.y); player.onGround = true; }

  // --- head bob + footsteps ---
  const speedNow = Math.hypot(player.vel.x, player.vel.z);
  if (player.onGround && speedNow > 0.5) player.bob += dt * speedNow * 1.15;
  const stepIndex = Math.floor(player.bob / Math.PI);
  if (stepIndex !== player._lastStep) {
    if (player.onGround && speedNow > 0.8) AudioFX.play('step');
    player._lastStep = stepIndex;
  }

  // --- apply to camera ---
  const bobY = Math.sin(player.bob * 2) * 0.05 * Math.min(speedNow / 6, 1);
  camera.position.set(player.pos.x, player.pos.y + EYE + bobY, player.pos.z);
  camera.rotation.set(player.pitch, player.yaw, 0, 'YXZ');

  // (health regen now comes from eating — see updateHunger)
}

// --- mouse look (pointer lock + drag fallback) ---
function onMouseLook(dx, dy) {
  if (!state.started || state.dead || state.paused) return;
  const sens = 0.0022;
  player.yaw -= dx * sens;
  player.pitch = clamp(player.pitch - dy * sens, -Math.PI / 2 + 0.05, Math.PI / 2 - 0.05);
}

const playable = () => state.started && !state.dead && !state.paused && !document.hidden;
function syncCursor() {
  input.pointerLocked = document.pointerLockElement === renderer.domElement;
  input.mode = input.pointerLocked ? 'locked' : input.dragging && playable() ? 'drag' : 'cursor';
  renderer.domElement.style.cursor = input.pointerLocked ? 'none' : 'crosshair';
  const hint = $('capture-hint');
  if (hint) hint.hidden = !playable() || input.pointerLocked || input.dragging;
}
function releaseInput() {
  input.keys.clear(); refreshInput(); input.dragging = false;
  input.pending = false; input.requestId++;
  if (document.pointerLockElement === renderer.domElement) document.exitPointerLock();
  syncCursor();
}
document.addEventListener('mousemove', (e) => {
  if (input.mode === 'locked') onMouseLook(e.movementX, e.movementY);
  else if (input.mode === 'drag') onMouseLook(e.clientX - input.lastX, e.clientY - input.lastY);
  input.lastX = e.clientX; input.lastY = e.clientY;
});
document.addEventListener('mouseup', () => { input.dragging = false; syncCursor(); });
window.addEventListener('blur', () => { if (playable()) openPause(); releaseInput(); });
document.addEventListener('visibilitychange', () => {
  if (document.hidden && state.started && !state.dead) openPause();
  if (document.hidden) releaseInput(); else syncCursor();
});

// =====================================================================
// S3 · TOM PEARL (3D) + GILDED ECHOES · CHASE AI
// =====================================================================
// ---- Tom Pearl: rigged GLB (upper-body character, hovers) ----
const tomLoader = new GLTFLoader();
let TOM_RIG = null; // { model, clip, bones, baseY } once loaded
const tomBonesOf = (model) => ({
  head: model.getObjectByName('Head') || null,
  lShoulder: model.getObjectByName('L_Shoulder') || null,
  rShoulder: model.getObjectByName('R_Shoulder') || null,
  lElbow: model.getObjectByName('L_Elbow') || null,
  rElbow: model.getObjectByName('R_Elbow') || null,
  spine: model.getObjectByName('Spine3') || null,
});
tomLoader.load(TOM_GLB_URL, (gltf) => {
  const model = gltf.scene;
  // normalize: scale the figure to ~2.25 units tall, resting at y = 0
  const box = new THREE.Box3().setFromObject(model);
  const h = Math.max(0.001, box.max.y - box.min.y);
  const s = 2.25 / h;
  model.scale.setScalar(s);
  model.position.y = -box.min.y * s;
  // simple IBL so the metallic skin isn't pitch black, plus shadows
  try {
    const pmrem = new THREE.PMREMGenerator(renderer);
    const env = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
    model.traverse((o) => {
      if (!o.isMesh) return;
      o.castShadow = true; o.receiveShadow = true;
      const mats = Array.isArray(o.material) ? o.material : [o.material];
      for (const m of mats) { if (m) { m.envMap = env; m.envMapIntensity = 1; } }
    });
  } catch (e) { /* non-fatal */ }
  TOM_RIG = {
    model,
    clip: (gltf.animations && gltf.animations[0]) || null,
    bones: tomBonesOf(model),
    baseY: -box.min.y * s,
  };
  if (world.tomPearl) attachTomRig(world.tomPearl);
}, undefined, (e) => console.warn('Tom Pearl GLB failed to load:', e));

// Swap the procedural stand-in body for the rigged model.
function attachTomRig(t) {
  if (!TOM_RIG || t.rigged) return;
  if (t.fallback) { t.group.remove(t.fallback); t.fallback = null; }
  const visual=cloneSkeleton(TOM_RIG.model);t.visual=visual;t.group.add(visual);
  const materialCopies=new Map();visual.traverse(o=>{if(o.isMesh){SHARED_GEOMS.add(o.geometry);const own=m=>{if(!materialCopies.has(m))materialCopies.set(m,m.clone());return materialCopies.get(m);};o.material=Array.isArray(o.material)?o.material.map(own):own(o.material);}});
  t.bones = tomBonesOf(visual);
  t.rigged = true;    t.mats = [];
  visual.traverse(o => { if (o.isMesh) for (const m of (Array.isArray(o.material) ? o.material : [o.material])) if (m && m.emissive && !t.mats.includes(m)) t.mats.push(m); });
  t.mixer = new THREE.AnimationMixer(visual);
  if (TOM_RIG.clip) {
    t.action = t.mixer.clipAction(TOM_RIG.clip);
    t.action.setLoop(THREE.LoopRepeat, Infinity);
    t.action.play();
  }
}

function goldMaterial() {
  return new THREE.MeshStandardMaterial({
    map: TEX.gold, bumpMap: TEX.gold, bumpScale: 0.02,
    color: 0xffe6a8, metalness: 0.9, roughness: 0.32,
    emissive: 0x6a4400, emissiveIntensity: 0.5,
  });
}

// Build a high-quality humanoid body (gold by default, custom material for husks).
function buildHumanoid(scale, faceMap, matOverride) {
  const group = new THREE.Group();
  const mat = matOverride || goldMaterial();
  const headMat = faceMap
    ? new THREE.MeshStandardMaterial({ map: faceMap, emissiveMap: faceMap, emissive: 0x7a4d10, emissiveIntensity: 0.5, metalness: 0.6, roughness: 0.42, bumpMap: TEX.gold, bumpScale: 0.012 })
    : mat;

  // torso + pelvis (smooth, tapered for a stronger silhouette)
  const torso = new THREE.Mesh(new THREE.CapsuleGeometry(0.44, 0.72, 8, 16), mat);
  torso.position.y = 1.55; torso.scale.set(1.16, 1, 0.82); group.add(torso);
  const pelvis = new THREE.Mesh(new THREE.SphereGeometry(0.42, 16, 12), mat);
  pelvis.position.y = 1.05; pelvis.scale.set(1.12, 0.72, 0.88); group.add(pelvis);

  // head (smooth)
  const head = new THREE.Mesh(new THREE.SphereGeometry(0.44, 16, 12), headMat);
  head.position.y = 2.32; head.scale.set(1, 1.12, 0.96); group.add(head);

  // neck
  const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.22, 0.3, 24, 4), mat);
  neck.position.y = 1.98; group.add(neck);

  // glowing eyes
  const eyeMat = new THREE.MeshStandardMaterial({ color: 0xfff2c8, emissive: 0xffb43a, emissiveIntensity: 2.6, roughness: 0.25 });
  const eyes = [];
  for (const side of [-1, 1]) {
    const eye = new THREE.Mesh(new THREE.SphereGeometry(0.08, 18, 14), eyeMat);
    eye.position.set(side * 0.165, 2.38, 0.375);
    group.add(eye); eyes.push(eye);
  }

  // crown of gold spikes
  const spikeGeo = new THREE.ConeGeometry(0.062, 0.34, 18, 6);
  for (let i = 0; i < 9; i++) {
    const a = (i / 9) * Math.PI * 2;
    const spike = new THREE.Mesh(spikeGeo, mat);
    spike.position.set(Math.cos(a) * 0.33, 2.72, Math.sin(a) * 0.33);
    spike.rotation.set(Math.cos(a) * 0.32, 0, -Math.sin(a) * 0.32);
    group.add(spike);
  }

  // shoulders + limbs
  const arms = [], legs = [];
  for (const side of [-1, 1]) {
    const shoulder = new THREE.Mesh(new THREE.SphereGeometry(0.24, 26, 20), mat);
    shoulder.position.set(side * 0.62, 1.86, 0); group.add(shoulder);

    const armPivot = new THREE.Group();
    armPivot.position.set(side * 0.62, 1.82, 0); group.add(armPivot);
    const upper = new THREE.Mesh(new THREE.CapsuleGeometry(0.165, 0.72, 6, 12), mat);
    upper.position.y = -0.46; armPivot.add(upper);
    const hand = new THREE.Mesh(new THREE.SphereGeometry(0.18, 22, 16), mat);
    hand.position.y = -0.92; armPivot.add(hand);
    arms.push(armPivot);

    const legPivot = new THREE.Group();
    legPivot.position.set(side * 0.28, 1.02, 0); group.add(legPivot);
    const thigh = new THREE.Mesh(new THREE.CapsuleGeometry(0.195, 0.78, 6, 12), mat);
    thigh.position.y = -0.52; legPivot.add(thigh);
    const foot = new THREE.Mesh(new THREE.SphereGeometry(0.22, 22, 16), mat);
    foot.scale.set(0.72, 0.42, 1.28);
    foot.position.set(0, -1.0, 0.14); legPivot.add(foot);
    legs.push(legPivot);
  }

  group.scale.setScalar(scale);
  return { group, arms, legs, head, eyes, mats: [mat, headMat] };
}

// ---- Tom Pearl singleton ----
function spawnTomPearl(x, z) {
  if (world.tomPearl) return;
  const group = new THREE.Group();
  group.position.set(x, terrainHeight(x, z), z);
  scene.add(group);
  const glow = new THREE.PointLight(0xffb43a, 1.8, 24, 2);
  glow.position.y = 2.2; group.add(glow);

  // aura (additive glow shell)
  const aura = new THREE.Mesh(
    new THREE.SphereGeometry(1.7, 32, 24),
    new THREE.MeshBasicMaterial({ color: 0xffb43a, transparent: true, opacity: 0.12, side: THREE.BackSide, blending: THREE.AdditiveBlending, depthWrite: false })
  );
  aura.position.y = 1.6; group.add(aura);

  // floating gold embers
  const emberCount = 60;
  const emberGeo = new THREE.BufferGeometry();
  const emberPos = new Float32Array(emberCount * 3);
  const emberVel = [];
  for (let i = 0; i < emberCount; i++) {
    emberPos[i*3] = (Math.random() - 0.5) * 3;
    emberPos[i*3+1] = Math.random() * 3.6;
    emberPos[i*3+2] = (Math.random() - 0.5) * 3;
    emberVel.push(0.25 + Math.random() * 0.5);
  }
  emberGeo.setAttribute('position', new THREE.BufferAttribute(emberPos, 3));
  const emberMat = new THREE.PointsMaterial({ color: 0xffcf6a, size: 0.09, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false });
  const embers = new THREE.Points(emberGeo, emberMat);
  embers.position.y = 0.2; group.add(embers);

  world.tomPearl = {
    group, fallback: null, rigged: false, mixer: null, action: null, bones: null,
    mats: null, head: null, arms: null, legs: null,
    glow, aura, embers, emberVel,
    alive:true, hp: 180 + Math.max(0, state.days - 2) * 60,   // grows stronger every night he walks
    speed: 5.0, touchRadius: 1.65, attackCooldown: 0, stun: 0, anim: 0, walkPhase: 0,
  };

  // rigged GLB when it has arrived; procedural stand-in until then
  if (TOM_RIG) {
    attachTomRig(world.tomPearl);
  } else {
    const built = buildHumanoid(1.15, null);
    group.add(built.group);
    world.tomPearl.fallback = built.group;
    world.tomPearl.mats = built.mats;
    world.tomPearl.head = built.head;
    world.tomPearl.arms = built.arms;
    world.tomPearl.legs = built.legs;
  }
}

function updateTomEffects(dt) {
  const t = world.tomPearl;
  if (!t || t.alive===false) return;
  // embers drift upward and wrap around
  const pos = t.embers.geometry.attributes.position;
  for (let i = 0; i < t.emberVel.length; i++) {
    pos.array[i*3+1] += t.emberVel[i] * dt;
    pos.array[i*3] += Math.sin(state.time * 1.5 + i) * dt * 0.15;
    if (pos.array[i*3+1] > 3.8) {
      pos.array[i*3+1] = 0;
      pos.array[i*3] = (Math.random() - 0.5) * 3;
      pos.array[i*3+2] = (Math.random() - 0.5) * 3;
    }
  }
  pos.needsUpdate = true;
  // aura + glow pulse
  t.aura.material.opacity = 0.1 + Math.sin(state.time * 2.4) * 0.05;
  t.glow.intensity = 1.6 + Math.sin(state.time * 3) * 0.35;
}

function updateTomPearl(dt) {
  const t = world.tomPearl;
  if (!t || !state.started || state.dead || state.paused) return;
  if(t.alive===false){if(deathSystem.updateDeath(t,dt))world.tomPearl=null;return;}
  const p = player.pos;
  const dx = p.x - t.group.position.x, dz = p.z - t.group.position.z;
  const dist = Math.hypot(dx, dz);

  // face the player
  const targetAngle = Math.atan2(dx, dz);
  let da = targetAngle - t.group.rotation.y;
  while (da > Math.PI) da -= Math.PI * 2;
  while (da < -Math.PI) da += Math.PI * 2;
  t.group.rotation.y += da * clamp(dt * 4, 0, 1);

  // head leans toward player (fallback head; rigged head bone applied after the mixer)
  const headLean = clamp(-Math.atan2(p.y + EYE - (t.group.position.y + 2.3), dist), -0.5, 0.5);
  if (!t.rigged && t.head) t.head.rotation.x = headLean;

  if (t.stun > 0) {
    t.stun -= dt;
    // knocked back: ease glow down
    if (!t.rigged && t.mats && !feedback.impacts.has(t.mats[0])) t.mats[0].emissiveIntensity = 0.25;
  } else {
    // stalking speed ramps up when close (aggro)
    const targetSpeed = dist < 26 ? 4.8 : 3.0;
    t.speed = lerp(t.speed, targetSpeed, clamp(dt * 1.2, 0, 1));
    if (dist > 1.0 && !t.windup) {
      const step = t.speed * dt;
      t.group.position.x += (dx / dist) * step;
      t.group.position.z += (dz / dist) * step;
    }
    if (!t.rigged && t.mats && !feedback.impacts.has(t.mats[0])) t.mats[0].emissiveIntensity = 0.55 + Math.sin(state.time * 3) * 0.12;
  }

  // terrain follow — he has no legs, so he floats just above the ground
  const hover = t.rigged ? 0.5 : 0;
  resolveCollision(t.group.position,.6);resolveBuildCollision(t.group.position,.6);
  t.group.position.y = groundHeightAt(t.group.position.x, t.group.position.z, t.group.position.y) + hover;

  // animation
  const moving = dist > 1.2 && t.stun <= 0;
  t.walkPhase += dt * (moving ? t.speed * 1.25 : 1.6);
  if (t.rigged && t.mixer) {
    // drive the walk cycle from the chase speed: faster chase = faster arm swing
    t.mixer.timeScale = t.stun > 0 ? 0.05 : (moving ? clamp(0.55 + t.speed * 0.17, 0, 2.2) : 0.16);
    t.mixer.update(dt);
    // hover bob (no legs — he drifts)
    t.group.position.y += Math.sin(state.time * 2.1) * 0.12 + (moving ? Math.abs(Math.sin(t.walkPhase)) * 0.05 : 0);
    // exaggerated running-arm pump on top of the walk cycle while chasing
    const pump = moving ? clamp((t.speed - 4.2) / 4.2, 0, 1) : 0;
    if (pump > 0 && t.bones) {
      const sw = Math.sin(t.walkPhase * 1.35) * 0.42 * pump;
      if (t.bones.lShoulder) t.bones.lShoulder.rotation.x += sw;
      if (t.bones.rShoulder) t.bones.rShoulder.rotation.x -= sw;
      if (t.bones.lElbow) t.bones.lElbow.rotation.x += Math.abs(sw) * 0.55;
      if (t.bones.rElbow) t.bones.rElbow.rotation.x += Math.abs(sw) * 0.55;
      if (t.bones.spine) t.bones.spine.rotation.y += Math.sin(t.walkPhase * 1.35) * 0.1 * pump;
    }
    if (t.bones.head) t.bones.head.rotation.x = headLean * 0.7;
  } else {
    const swing = moving ? Math.sin(t.walkPhase) : Math.sin(state.time * 1.5) * 0.12;
    if (t.arms) {
      t.arms[0].rotation.x = swing * 0.9;
      t.arms[1].rotation.x = -swing * 0.9;
      t.legs[0].rotation.x = -swing * 1.0;
      t.legs[1].rotation.x = swing * 1.0;
    }
    t.group.position.y += Math.abs(Math.sin(t.walkPhase)) * (moving ? 0.08 : 0.02);
  }
  t.glow.intensity = 1.4 + Math.sin(state.time * 3) * 0.3;

  // attack / touch
  t.attackCooldown -= dt;    if (Math.abs(p.y-t.group.position.y)<3 && dist < 3.4 && t.attackCooldown <= 0 && t.stun <= 0 && !t.windup) { t.windup = 1.1; t.attackCooldown = 2.8; AudioFX.play('boss'); }
  if (t.windup > 0) {
    t.windup -= dt; t.aura.material.opacity = 0.28; t.glow.intensity = 4;
    if (t.windup <= 0 && dist < 3.6 && Math.abs(p.y-t.group.position.y)<3) {
    damagePlayer(32, 'TOM PEARL CAUGHT YOU');
    t.attackCooldown = 1.15;
    // knock the player back
    const kb = 5.5;
    player.vel.x += (dx / (dist || 1)) * -kb;
    player.vel.z += (dz / (dist || 1)) * -kb;
    player.vel.y = 3.2;
    }
  }

}

// ---- husks (night enemies) ----
const HUSK_MAT = new THREE.MeshStandardMaterial({ map: TEX.bark, color: 0x686454, roughness: .98, metalness: 0, emissive: 0x2a0d0d, emissiveIntensity: 0 });
function spawnHusk(x, z) {
  const built = ART.character('husk',1.92) || buildHumanoid(.82,null,HUSK_MAT.clone());
  if(built.head)built.head.scale.setScalar(.8);if(built.visual)built.visual.scale.x=.9;
  // A ragged hood and draped coat give the husk its own recognizable silhouette.
  const cloth=new THREE.MeshStandardMaterial({map:TEX.wood,color:0x62594a,roughness:1,side:THREE.DoubleSide});
  const points=[new THREE.Vector2(.6,.8),new THREE.Vector2(.53,1.15),new THREE.Vector2(.46,1.6),new THREE.Vector2(.59,1.85)];
  if(!built.mixer){
    const coat=new THREE.Mesh(new THREE.LatheGeometry(points,12),cloth);built.group.add(coat);
    const hood=new THREE.Mesh(new THREE.SphereGeometry(.49,12,10,0,Math.PI*2,0,Math.PI*.72),cloth);hood.position.set(0,2.32,-.06);built.group.add(hood);built.mats.push(cloth);
  }else cloth.dispose();
  built.group.position.set(x, terrainHeight(x, z), z);
  scene.add(built.group);
  world.husks.push({ ...built, hp: 24, speed: 7.8, patrolAngle:Math.random()*Math.PI*2, alert:0, walkPhase: Math.random() * 6, alive: true, attackCooldown: 0, deathT: 0 });
}
function updateHusks(dt) {
  if (state.paused) return;
  const p = player.pos;
  for (let i = world.husks.length - 1; i >= 0; i--) {
    const e = world.husks[i];
    if (!e.alive) {
      if(deathSystem.updateDeath(e,dt))world.husks.splice(i,1);
      continue;
    }
    const dx = p.x - e.group.position.x, dz = p.z - e.group.position.z;
    const dist = Math.hypot(dx, dz);
    e.alert=Math.max(0,e.alert-dt);if(dist<(state.night?28:18)&&Math.abs(p.y-e.group.position.y)<4)e.alert=7;
    if(e.alert===0)e.patrolAngle+=Math.sin(state.time*.4+e.walkPhase)*dt*.3;
    const targetAngle = e.alert>0?Math.atan2(dx,dz):e.patrolAngle;
    let da = targetAngle - e.group.rotation.y;
    while (da > Math.PI) da -= Math.PI * 2;
    while (da < -Math.PI) da += Math.PI * 2;
    e.group.rotation.y += da * clamp(dt * 5, 0, 1);

    e.stun = Math.max(0, (e.stun || 0) - dt);
    if (dist > 1.0 && !e.stun && !e.windup) {
      const step = (e.alert>0?e.speed:1.1)*dt;
      const nx=e.group.position.x+Math.sin(targetAngle)*step,nz=e.group.position.z+Math.cos(targetAngle)*step;
      if(!waterColumnAt(nx,nz)&&Math.abs(terrainHeight(nx,nz)-e.group.position.y)<.9){e.group.position.x=nx;e.group.position.z=nz;}
    }
    resolveCollision(e.group.position,.48);resolveBuildCollision(e.group.position,.48);
    e.group.position.y = groundHeightAt(e.group.position.x, e.group.position.z, e.group.position.y);
    e.walkPhase += dt * e.speed * 1.3;
    const swing = Math.sin(e.walkPhase);
    if(e.mixer)ART.animateCharacter(e,dt,e.alert>0&&!e.stun&&!e.windup?'run':'idle');
    else {e.arms[0].rotation.x=swing*.9;e.arms[1].rotation.x=-swing*.9;e.legs[0].rotation.x=-swing;e.legs[1].rotation.x=swing;}
    if(e.head)e.head.rotation.z=Math.sin(state.time*2)*.12;

    e.attackCooldown -= dt;
    if (Math.abs(p.y-e.group.position.y)<2.5 && dist < 3.2 && e.attackCooldown <= 0 && !e.stun && !e.windup) { e.windup = .65; e.attackCooldown = 1.8; AudioFX.play('mob'); }
    if (e.windup > 0) {
      e.windup -= dt; e.arms[0].rotation.x = -1.8; e.arms[1].rotation.x = -1.8;
      if (e.windup <= 0 && dist < 2.9 && Math.abs(p.y-e.group.position.y)<2.5) {
      damagePlayer(12, 'A HUSK OVERWHELMED YOU');
      e.attackCooldown = 1.1;
      const kb = 4;
      player.vel.x += (dx / (dist || 1)) * -kb;
      player.vel.z += (dz / (dist || 1)) * -kb;
      }
    }

  }
}
function hurtHusk(e, dmg) {
  if (!e.alive) return false;
  e.hp -= dmg;
  // flash + knockback away from player
  impactFeedback(e); e.stun = 0.45;
  e.windup = 0;
  const dx = e.group.position.x - player.pos.x, dz = e.group.position.z - player.pos.z;
  const d = Math.hypot(dx, dz) || 1;
  e.group.position.x += (dx / d) * 1.2;
  e.group.position.z += (dz / d) * 1.2;
  e.alert=8;
  if (e.hp <= 0) { deathSystem.beginDeath(e,'husk',{fiber:2,iron:1}); return true; }
  return false;
}

