// =====================================================================
scene.add(camera);   // so the tool viewmodel (child of camera) renders

// ---- tool / weapon catalog (hotbar order = number keys 1..7) ----
const WEAPONS = [
  { id: 'hand',     name: 'FISTS',         icon: '', dmg: 2,  chop: 1,   mine: 0.5, cost: null },
  { id: 'club',     name: 'WOOD CLUB',     icon: '', dmg: 6,  chop: 1.4, mine: 0.7, cost: { wood: 3 } },
  { id: 'axe',      name: 'WOOD AXE',      icon: '', dmg: 8,  chop: 3,   mine: 1.2, cost: { wood: 5 } },
  { id: 'pick',     name: 'STONE PICKAXE', icon: '', dmg: 9,  chop: 1.6, mine: 4,   cost: { wood: 3, stone: 3 } },
  { id: 'stoneAxe', name: 'STONE AXE',     icon: '', dmg: 12, chop: 5,   mine: 1.6, cost: { wood: 3, stone: 4 }, bench: true },
  { id: 'sword',    name: 'STONE SWORD',   icon: '', dmg: 18, chop: 1,   mine: 0.6, cost: { wood: 2, stone: 6 }, bench: true },
  { id: 'iron',     name: 'IRON BLADE',    icon: '', dmg: 24, chop: 1.2, mine: 1.4, cost: { wood: 2, iron: 8 }, bench: true },
  { id: 'gold',     name: 'GOLD BLADE',    icon: '', dmg: 30, chop: 2,   mine: 1,   cost: { wood: 2, gold: 5 }, bench: true },
  { id: 'shovel',   name: 'FIELD SHOVEL', icon: '', dmg: 4, chop: .5, mine: .3, cost: {wood:3,stone:2}, shovel:true },
  { id: 'knife',    name: 'HUNTING KNIFE', icon: '', dmg: 10, chop: .7, mine: .3, cost: {wood:2,stone:3} },
  { id:'bow',name:'ASH BOW',icon:'',dmg:18,chop:0,mine:0,cost:{wood:8,fiber:4,stone:3},bench:true,ranged:true },
  { id: 'torch',    name: 'TORCH',         icon: '', dmg: 3,  chop: 0.6, mine: 0.4, cost: { wood: 2 }, torch: true },
];

const TOOL_PROFILE = {
  bow:[.85,60,5,'jab','bow','A recurved ash bow. Moving flint arrows arc with gravity and can be recovered.'],
  hand:[.36,1.9,2,'jab','hit','A quick close-range strike.'],
  club:[.76,2.7,9,'bash','chop','Heavy stagger; cheap protection, poor harvesting.'],
  axe:[.64,2.8,7,'chop','chop','Chops timber three times faster than fists.'],
  pick:[.78,2.7,10,'mine','mine','Breaks rock and exposed ore; not a digging tool.'],
  stoneAxe:[.7,3,8,'chop','chop','Balanced stone head for efficient timber harvesting.'],
  sword:[.58,3.2,8,'slash','blade','Fast stone edge; combat rather than harvesting.'],
  iron:[.48,3.35,7,'slash','blade','Weathered iron edge; fast, efficient combat.'],
  gold:[.94,3.65,14,'cleave','blade','Long gilded claymore; slow, powerful committed strikes.'],
  shovel:[.68,3.6,8,'scoop','dig','Left click scoops soil; V or right click fills a scoop.'],
  knife:[.3,2.2,3,'jab','blade','Short reach; rapid low-stamina hunting thrusts.'],
  torch:[.5,3.6,0,'jab','craft','Carry light; place with one wood, X recovers it.'],
};
for(const w of WEAPONS){const [cooldown,reach,stamina,motion,impact,description]=TOOL_PROFILE[w.id];Object.assign(w,{cooldown,reach,stamina,motion,impact,description});w.icon=`<img class="item-icon" src="${iconPath(weaponItemId(w.id))}" alt="${w.name}">`;}
const items=createItems(WEAPONS);
Object.defineProperty(state,'inv',{get:()=>items.inv,set:()=>{throw Error('Inventory must be restored through items.restore');}});
// Legacy ownership queries are derived. No unlock set stores owned equipment.
Object.defineProperty(state,'crafted',{get:()=>new Set(['hand',...items.slots.filter(Boolean).map(s=>items.defs[s.id]?.weaponId).filter(Boolean)])});
Object.defineProperty(state,'armor',{get:()=>items.reduction()>0});
function activeWeapon(){const d=items.defs[items.slots[state.sel]?.id];return WEAPONS.find(w=>w.id===d?.weaponId)||WEAPONS[0];}


// ---- tool viewmodel: library-owned models, with grip-relative pivots ----
const toolView = new THREE.Group();
const toolHandle = new THREE.Mesh(
  new THREE.CylinderGeometry(0.03, 0.042, 0.72, 12, 6),
  new THREE.MeshStandardMaterial({ color: 0x7a5228, metalness: 0.25, roughness: 0.7 })
);
toolHandle.position.y = -0.18; toolView.add(toolHandle);
const toolHead = new THREE.Mesh(
  new THREE.BoxGeometry(0.3, 0.16, 0.09),
  new THREE.MeshStandardMaterial({ color: 0x9a9a94, metalness: 0.35, roughness: 0.55 })
);
toolHead.position.set(0.02, 0.14, 0); toolView.add(toolHead);
const toolFist = new THREE.Mesh(
  new THREE.SphereGeometry(0.11, 16, 12),
  new THREE.MeshStandardMaterial({ color: 0xc98f63, roughness: 0.8 })
);
toolFist.position.y = 0.02; toolView.add(toolFist);
toolView.position.set(0.5, -0.42, -0.95);
toolView.rotation.set(-0.35, 0.2, 0.15);
camera.add(toolView);
let toolSwing = 0;
const equippedModels = new Map();
const gripHeight={bow:[1.15,.5],club:[.95,.16],axe:[.85,.27],stoneAxe:[.9,.27],pick:[.92,.25],shovel:[1.05,.65],sword:[.98,.13],iron:[1.13,.08],gold:[1.3,.09],knife:[.62,.17],torch:[.92,.24]};
for(const [id,[height,grip]] of Object.entries(gripHeight)){
  const model=ART.instance(id,height,grip);if(!model)continue;
  model.visible=false;model.rotation.y=['axe','stoneAxe','pick'].includes(id)?-.35:0;
  model.traverse(o=>{o.castShadow=false;o.receiveShadow=false;});toolView.add(model);equippedModels.set(id,model);
}

function updateToolView() {
  const w = activeWeapon();
  toolSwing=0;toolView.position.z=-.95;toolView.rotation.set(-.35,.2,.15);
  for(const [id,model]of equippedModels)model.visible=id===w.id;
  const isHand = w.id === 'hand';
  const real=equippedModels.has(w.id);
  toolFist.visible = isHand;
  if(real){toolHandle.visible=false;toolHead.visible=false;return;}
  toolHandle.visible = !isHand;
  toolHead.visible = !isHand;
  if (isHand) return;
  const isBlade = w.id === 'sword' || w.id === 'gold';
  toolHead.scale.set(isBlade ? 0.22 : 1, isBlade ? 3 : 1, isBlade ? 0.4 : 1);
  toolHead.position.y = isBlade ? 0.32 : 0.14;
  toolHead.material.color.setHex(
    w.id === 'club' ? 0x8a5a2c : w.id === 'gold' ? 0xffd35c
    : w.id === 'stoneAxe' || w.id === 'pick' || w.id === 'sword' ? 0x9a9a94 : 0xb08040
  );
  toolHead.material.metalness = w.id === 'gold' ? 0.8 : 0.35;
}

// ---- hotbar (Minecraft-style numbered slots) ----
function buildHotbar() { inventoryUI.hotbar(); }
function updateHotbar(){inventoryUI.hotbar();}
function selectSlot(i) {
  if (!Number.isInteger(i) || i < 0 || i >= 9) return;
  state.sel = i;
  updateHotbar();
  updateToolView();
  const s=items.slots[i],d=items.defs[s?.id];
  if(state.started){AudioFX.play('pickup');showToast(d?inventoryUI.icon(s.id)+' '+d.name:'Empty slot · unarmed gathering',1200);}
}

// ---- hearts (Minecraft-style health) ----
function updateVitals() {
  dom.hpBar.style.width = state.hp + '%';
  dom.hpLabel.textContent = 'HEALTH ' + Math.ceil(state.hp);
  dom.hungerBar.style.width = state.hunger + '%';
  dom.hungerLabel.textContent = 'HUNGER ' + Math.ceil(state.hunger);
  dom.stBar.style.width = state.stamina + '%';
  dom.stLabel.textContent = (state.stamina<10?'EXHAUSTED · ':'STAMINA ') + Math.ceil(state.stamina);
  dom.breathBar.style.width = state.breath + '%';
  dom.breathWrap.style.visibility = state.breath >= 99.5 ? 'hidden' : 'visible';
}

// ---- toasts ----
function showToast(html, ms = 3200) {
  const t = document.createElement('div');
  t.className = 'toast';
  t.innerHTML = html;
  dom.toasts.appendChild(t);
  const previous = feedback.toasts.find(q => q.html === html);
  if (previous) { previous.el.remove(); feedback.toasts.splice(feedback.toasts.indexOf(previous), 1); }
  feedback.toasts.push({ el: t, html, life: ms / 1000 });
  while (feedback.toasts.length > 3) feedback.toasts.shift().el.remove();
}

// ---- crafting ----
function canCraft(w) {
  if (w.bench && (craftMode !== 'bench' || !nearStructure('workbench', 5))) return false;
  if (!w.cost) return true;
  for (const k in w.cost) if ((state.inv[k] || 0) < w.cost[k]) return false;
  return true;
}
function craftWeapon(i) {
  const w = WEAPONS[i];
  if (!w || !w.cost || dom.craft.classList.contains('hidden') || !canCraft(w) || !state.started || state.dead) return false;
  if(!items.transaction(w.cost,{[weaponItemId(w.id)]:1}))return false;
  AudioFX.play('craft');
  showToast('CRAFTED <b>' + w.name + '</b>');
  renderCraftList();
  const owned=items.slots.findIndex(s=>s?.id===weaponItemId(w.id));
  // Acquisition never overwrites a player-assigned quickbar slot.
  if(owned>=0&&owned<9)selectSlot(owned);
  survival.saveGame(false); renderInventory(); return true;
}
let craftMode = 'hand';
function renderCraftList() {
  const benchMode = craftMode === 'bench';
  $('craft-tag').textContent = benchMode ? 'WORKBENCH · ADVANCED RECIPES' : 'FIELD CRAFTING · BASIC RECIPES';
  $('craft-title').innerHTML = benchMode ? 'THE<br><em>WORKSHOP</em>' : 'FIELD<br><em>CRAFTING</em>';
  dom.craft.classList.toggle('workshop',benchMode);
  dom.craftList.innerHTML = '';
  const rowFor = (w, i) => {
    const row = document.createElement('div');
    row.className = 'recipe';
    const cost = w.cost
      ? Object.entries(w.cost).map(([k, v]) => '<span class="'+((state.inv[k]||0)<v?'missing':'available')+'">'+inventoryUI.icon(k)+' <b>'+(state.inv[k]||0)+' / '+v+'</b> '+k.toUpperCase()+'</span>').join('  ·  ')
      : 'ALWAYS WITH YOU';
    const info = document.createElement('div');
    info.innerHTML = '<div class="r-name">' + w.icon + '  ' + w.name + '</div>' +
      '<div class="r-cost">' + cost + '</div><div class="r-desc">'+w.description+'</div><div class="r-cost">DAMAGE '+w.dmg+' · REACH '+w.reach+'m · STAMINA '+w.stamina+(w.bench?' · WORKBENCH REQUIRED':' · FIELD RECIPE')+'</div>';
    row.appendChild(info);
    const btn = document.createElement('button');
    btn.className = 'r-btn';
    btn.textContent = w.bench && !nearStructure('workbench', 5) ? 'NEEDS BENCH' : !canCraft(w) ? 'NEED MATERIALS' : 'CRAFT';
    btn.disabled = !canCraft(w);
    btn.addEventListener('click', () => craftWeapon(i));
    row.appendChild(btn);
    return row;
  };
  if(!benchMode){WEAPONS.forEach((w, i) => { if (!w.bench && w.cost) dom.craftList.appendChild(rowFor(w, i)); });survival.renderExtraRecipes('basic');}
  if (!benchMode) {
    const note = document.createElement('div');
    note.className = 'craft-note';
    note.innerHTML = 'WORKBENCH ONLY · <b>STONE AXE · STONE SWORD · IRON / GOLD BLADES · HIDE ARMOR</b><br>Build one with <b>B</b>, then press <b>E</b> on it for the full advanced menu.';
    dom.craftList.appendChild(note);
  } else {
    const section = document.createElement('div');
    section.className = 'craft-section';
    section.textContent = '— WORKBENCH ONLY —';
    dom.craftList.appendChild(section);
    WEAPONS.forEach((w, i) => { if (w.bench) dom.craftList.appendChild(rowFor(w, i)); });
    survival.renderExtraRecipes('bench');
  }
}
function openCraft(mode) {
  if (!state.started || state.dead || state.paused) return;
  if(mode==='bench'&&!nearStructure('workbench',5)){showToast('Interact with a workbench first',1500);return;}
  craftMode = mode === 'bench' ? 'bench' : 'hand';
  renderCraftList();
  dom.craft.classList.remove('hidden');
  dom.craft.classList.add('fade-in');
  state.paused = true;
  releaseInput();
  resetFeedback(); AudioFX.setUnderwater(false);
}
function closeCraft() {
  dom.craft.classList.add('hidden');
  if (state.dead || !state.started) return;
  state.paused = false;
  AudioFX.resume();
  lockPointer();
  syncCursor();
}

// ---- inventory / resource pack (I) ----
function renderInventory(){inventoryUI.render();}
function closeInventory() {
  inventoryUI.closePreview();
  $('inventory-overlay').classList.add('hidden');
  if (state.dead || !state.started) return;
  state.paused = false;
  AudioFX.resume();
  lockPointer();
  syncCursor();
}
function toggleInventory() {
  if (!state.started || state.dead || build.mode) return;
  if (!$('inventory-overlay').classList.contains('hidden')) { closeInventory(); return; }
  if (state.paused) return;   // another menu owns the screen
  renderInventory();
  state.paused = true;
  releaseInput();
  resetFeedback(); AudioFX.setUnderwater(false); AudioFX.play('lore');
  $('inventory-overlay').classList.remove('hidden');
  $('inventory-overlay').classList.add('fade-in');
}

// =====================================================================
// S5 · HARVESTING · COMBAT · DAMAGE / DEATH
// =====================================================================
// ---- harvesting (chop trees / mine rocks) ----
function findHarvestTarget() {
  const fwd = new THREE.Vector3(-Math.sin(player.yaw), 0, -Math.cos(player.yaw));
  let best = null, bestScore = -1;
  for (const h of world.harvestables) {
    if (h.dead || h.hidden) continue;
    const dx = h.x - player.pos.x, dz = h.z - player.pos.z;
    const d = Math.hypot(dx, dz);
    if (d > h.r + 1.8 || d > activeWeapon().reach + .4 || Math.abs(h.group.position.y - player.pos.y) > 3.5) continue;
    const dot = (dx / (d || 1)) * fwd.x + (dz / (d || 1)) * fwd.z;
    if (dot < 0.5) continue;
    const score = dot * 2 - d * 0.3;
    if (score > bestScore) { bestScore = score; best = h; }
  }
  return best;
}
function damageHarvest(h, w) {
  if(h.dead||h.hidden)return;
  const isRock = h.type === 'rock' || h.type === 'ore';
  const isBush = h.type === 'bush';
  h.hp -= isRock ? w.mine : w.chop;
  h.shake = 1;
  spawnBurst(new THREE.Vector3(h.x, player.pos.y + 1.1, h.z), isRock ? 0xb8b8b0 : isBush ? 0xc85a64 : 0xc2924f);
  AudioFX.play(isRock ? 'mine' : 'chop');
  flashHitmarker();
  if (h.hp <= 0 && !h.dead) {
    h.dead = true;
    h.group.visible = false;
    const ci = world.colliders.findIndex((c) => Math.abs(c.x - h.x) < 0.01 && Math.abs(c.z - h.z) < 0.01);
    if (ci >= 0) world.colliders.splice(ci, 1);
    if (h.type === 'ore') {
      world.oreTaken.add(hkey(h.x, h.z));
      const gold = h.oreKind === 'gold';
      const gain = gold ? 2 + Math.floor(Math.random() * 2) : 3 + Math.floor(Math.random() * 3);
      state.inv[gold ? 'gold' : 'iron'] += gain;
      showToast('+' + gain + ' <b>' + (gold ? 'GOLD' : 'IRON') + '</b>', 2000);
    } else if (isBush) {
      world.chopped.add(hkey(h.x, h.z));
      const gain = 2 + Math.floor(Math.random() * 2);
      state.inv.berries += gain; items.add('fiber',1);
      showToast('+' + gain + ' <b>BERRIES</b>  ·  PRESS <b>F</b> TO EAT', 2200);
    } else {
      world.chopped.add(hkey(h.x, h.z));
      const gain = isRock ? 3 + Math.round(w.mine) : 3 + Math.round(w.chop * 0.8);
      state.inv[isRock ? 'stone' : 'wood'] += gain;
      showToast('+' + gain + ' <b>' + (isRock ? 'STONE' : 'WOOD') + '</b>', 2000);
    }
    AudioFX.play('pickup');
  }
  if(h.id)world.harvestState.set(h.id,{hp:h.hp,dead:h.dead,hidden:h.hidden});
}
function updateHarvest(dt) {
  for (const h of world.harvestables) {
    if (h.dead || h.shake <= 0) continue;
    h.shake = Math.max(0, h.shake - dt * 3.2);
    h.group.rotation.z = Math.sin(state.time * 38) * 0.055 * h.shake;
  }
}

// ---- particle bursts ----
world.bursts = [];
function spawnBurst(pos, color = 0xffd27a) {
  if(world.bursts.length>=32){const old=world.bursts.shift();old.pts.removeFromParent();old.pts.geometry.dispose();old.pts.material.dispose();}
  const n = 22;
  const geo = new THREE.BufferGeometry();
  const arr = new Float32Array(n * 3);
  const vel = [];
  for (let i = 0; i < n; i++) {
    arr[i*3] = pos.x; arr[i*3+1] = pos.y; arr[i*3+2] = pos.z;
    vel.push(new THREE.Vector3((Math.random()-0.5)*10, Math.random()*8, (Math.random()-0.5)*10));
  }
  geo.setAttribute('position', new THREE.BufferAttribute(arr, 3));
  const mat = new THREE.PointsMaterial({ map: TEX.glow, color, size: 0.45, transparent: true, opacity: 1, depthWrite: false, blending: THREE.AdditiveBlending });
  const pts = new THREE.Points(geo, mat);
  pts.frustumCulled = false;
  scene.add(pts);
  world.bursts.push({ pts, vel, life: 0.6 });
}
function updateBursts(dt) {
  for (let i = world.bursts.length - 1; i >= 0; i--) {
    const b = world.bursts[i];
    b.life -= dt;
    const pos = b.pts.geometry.attributes.position;
    for (let j = 0; j < b.vel.length; j++) {
      pos.array[j*3]   += b.vel[j].x * dt;
      pos.array[j*3+1] += b.vel[j].y * dt;
      pos.array[j*3+2] += b.vel[j].z * dt;
      b.vel[j].y -= 12 * dt;
    }
    pos.needsUpdate = true;
    b.pts.material.opacity = Math.max(0, b.life / 0.6);
    if (b.life <= 0) { scene.remove(b.pts); b.pts.geometry.dispose(); b.pts.material.dispose(); world.bursts.splice(i, 1); }
  }
}

// ---- combat resolution ----
function swingWeapon() {
  if (!state.started || state.dead || state.paused) return;
  if (build.mode) { confirmBuild(); return; }
  if(ranged.pickup())return;
  if (!findCombatTarget() && (useCaveEntrance() || useWorldObject())) return;
  if (state.toolCooldown > 0) return;
  if(inventoryUI.use())return;
  const w = activeWeapon();
  if(w.ranged){ranged.beginDraw(w);return;}
  if (!state.crafted.has(w.id)) {
    showToast('CRAFT A TOOL FIRST  ·  PRESS <b>C</b>', 1800);
    return;
  }
  if(state.stamina < w.stamina){showToast('Catch your breath · insufficient stamina',1200);return;}
  state.stamina-=w.stamina; state.staminaWait=STAMINA.delay;
  state.toolCooldown = w.cooldown;
  toolSwing = 1;
  AudioFX.play('swing');

  // holding a torch: clicking places a light instead of swinging
  if (w.torch) {
    const spot = pickDigPoint();
    if (spot) placeTorch(spot);
    return;
  }

  // Combat takes priority over scenery, with one nearest-target dispatch.
  const target = findCombatTarget();
  if (target) { target.hurt(w.dmg); if(w.id==='club')target.e.stun=Math.max(target.e.stun||0,.85);AudioFX.play(w.impact); flashHitmarker(); return; }
  const h = findHarvestTarget();    if (h) { damageHarvest(h, w); return; }
  // nothing to hit: dig into the ground where you are looking
  const dig = pickDigPoint();
  if (dig && w.shovel) digGround(dig, w);
}
function findCombatTarget() {
  const direction = new THREE.Vector3(); camera.getWorldDirection(direction);
  let best = null, distance = Infinity;
  const candidates = [
    ...world.mobs.map(e => ({ e, hurt: dmg => hurtMob(e, dmg) })),
    ...world.crawlers.map(e => ({ e, hurt: dmg => hurtCrawler(e, dmg) })),
    ...world.husks.map(e => ({ e, hurt: dmg => hurtHusk(e, dmg) })),
  ];
  if (world.tomPearl) candidates.push({ e: world.tomPearl, hurt: hurtTomPearl });
  for (const candidate of candidates) {
    const e = candidate.e;
    if (e.alive === false) continue;
    const offset = e.group.position.clone().add(new THREE.Vector3(0, e === world.tomPearl ? 1.6 : 0.9, 0)).sub(camera.position);
    const d = offset.length();
    if (d < activeWeapon().reach && d < distance && offset.normalize().dot(direction) > (activeWeapon().motion==='jab'?.78:.62)) { best = candidate; distance = d; }
  }
  return best;
}
function hurtTomPearl(dmg) {
  const t = world.tomPearl;
  if (!t || t.alive===false) return;
  t.hp -= dmg;
  t.stun = Math.max(t.stun, 0.55); t.windup = 0; impactFeedback(t);
  const dx = t.group.position.x - player.pos.x, dz = t.group.position.z - player.pos.z;
  const d = Math.hypot(dx, dz) || 1;
  t.group.position.x += (dx / d) * 1.2;
  t.group.position.z += (dz / d) * 1.2;
  spawnBurst(new THREE.Vector3(t.group.position.x, t.group.position.y + 2, t.group.position.z), 0xffb43a);
  if (t.hp <= 0) banishTomPearl();
}

function banishTomPearl() {
  const t = world.tomPearl;
  if (!t) return;
  spawnBurst(new THREE.Vector3(t.group.position.x, t.group.position.y + 2, t.group.position.z), 0xffe6a8);
  if(!deathSystem.beginDeath(t,'boss',{pearlCore:1,gold:5}))return;
  state.danger = 0;
  AudioFX.play('banish');
  showToast('<b>TOM PEARL</b> FALLS · wait for his remains to reveal the core', 4200);
}

const feedback = { hit: 0, damage: 0, toasts: [], impacts: new Map() };
function resetFeedback() {
  feedback.hit = feedback.damage = state.flash = state.danger = 0;
  feedback.toasts.length = 0; dom.toasts.replaceChildren();
  for (const [mat, f] of feedback.impacts) { mat.emissive.copy(f.color); mat.emissiveIntensity = f.intensity; }
  feedback.impacts.clear();
  dom.hitmarker.classList.remove('show'); dom.prompt.classList.remove('show');
  for (const el of [dom.damageFlash, dom.lightning, dom.dangerVignette, dom.underwater]) el.style.opacity = '0';
}
function impactFeedback(entity) {
  for (const mat of entity.mats || []) {
    if (!mat.emissive) continue;
    const original = feedback.impacts.get(mat);
    feedback.impacts.set(mat, { color: original ? original.color : mat.emissive.clone(), intensity: original ? original.intensity : mat.emissiveIntensity, life: 0.2 });
    mat.emissive.setHex(0x992828); mat.emissiveIntensity = 1;
  }
}
function updateFeedback(dt) {
  if (input.pending && performance.now() - input.requestedAt > 1500) { input.pending = false; syncCursor(); }
  feedback.hit = Math.max(0, feedback.hit - dt); feedback.damage = Math.max(0, feedback.damage - dt);
  dom.hitmarker.classList.toggle('show', feedback.hit > 0);
  dom.damageFlash.style.opacity = String(feedback.damage * 2.5);
  for (const [mat, f] of feedback.impacts) {
    f.life -= dt;
    if (f.life <= 0) { mat.emissive.copy(f.color); mat.emissiveIntensity = f.intensity; feedback.impacts.delete(mat); }
  }
  for (let i = feedback.toasts.length - 1; i >= 0; i--) {
    const t = feedback.toasts[i]; t.life -= dt;
    t.el.style.opacity = String(clamp(t.life / 0.5, 0, 1));
    if (t.life <= 0) { t.el.remove(); feedback.toasts.splice(i, 1); }
  }
}
function flashHitmarker() { feedback.hit = 0.16; }

// ---- player damage + death ----
function damagePlayer(amount, reason) {
  if (state.dead || !state.started || state.paused) return;
  const environmental=/DROWN|STARVATION/i.test(reason||'');
  state.hp = clamp(state.hp - amount * (environmental?1:1-items.reduction()), 0, 100);
  feedback.damage = 0.22;
  AudioFX.play('hurt');
  if (state.hp <= 0) die(reason);
}
function die(reason) {
  if (state.dead) return;
  state.dead = true;
  state.paused = false;
  dom.pause.classList.add('hidden'); dom.craft.classList.add('hidden'); $('inventory-overlay').classList.add('hidden');
  cancelBuild();
  for (const id of ['build-overlay','storage-overlay','journal-overlay']) $(id).classList.add('hidden');
  dom.deathReason.textContent = reason || 'THE WILD TOOK YOU';
  dom.death.classList.add('hidden');
  deathSystem.startPlayerDeath(); inventoryUI.closePreview();
  releaseInput(); resetFeedback();
  AudioFX.play('death');
}

// =====================================================================
// S5 · SURVIVAL: TOM PEARL AWAKENING · INTERACTION PROMPTS
// =====================================================================
// Tom Pearl does NOT chase from the start: he walks only after the second night.
function checkBossAwaken() {
  if (world.tomPearl || !state.started || state.dead) return;
  if (state.days < 2 || !state.night || state.lastTomDay === state.days) return;
  awakenTomPearl();
}
function awakenTomPearl() {
  const a = Math.random() * Math.PI * 2;
  const r = 44 + Math.random() * 10;
  const x = player.pos.x + Math.cos(a) * r, z = player.pos.z + Math.sin(a) * r;
  spawnTomPearl(x, z);
  state.lastTomDay = state.days;
  AudioFX.play('boss');
  showToast('<b>TOM PEARL</b> WALKS TONIGHT', 5200);
}

// ---- interaction prompts (what a click will do) ----
function updateInteractionPrompt() {
  let text = '';
  if (state.started && !state.dead && !state.paused) {
    const h = findHarvestTarget();
    if (h) text = '[ CLICK ]  ' + (h.type === 'rock' ? 'MINE ROCK' : h.type === 'bush' ? 'PICK BERRIES' : h.type === 'ore' ? 'MINE ORE' : 'CHOP TREE');
    else if (pickDigPoint() && activeWeapon().shovel) text = terrainEditReason(pickDigPoint()) || '[ CLICK / E ] SCOOP +1 SOIL · RIGHT CLICK / V REFILL −1';
  }
  if (playable()) {
    const torch=aimedTorch();
    const pickup=ranged.aimedLoot();
    const campText = pickup ? `[ E / CLICK ] TAKE ${items.defs[pickup.id].name.toUpperCase()} ×${pickup.qty}` : torch ? '[ X ] DISMANTLE THIS TORCH · RECOVER 1 WOOD' : caveEntranceText() || survival.interactionText();
    if (campText) text = campText;
    else if (activeWeapon().torch) text = '[ CLICK / E ] PLACE TORCH · 1 WOOD';
    else if (findCombatTarget()) text = '[ CLICK / E ] ATTACK';
  }
  dom.prompt.textContent = text || '[ CLICK / E ]  SWING';
  dom.prompt.classList.toggle('show', !!text && state.started && !state.dead && !state.paused);
}

// =====================================================================
// S6 · PROCEDURAL AUDIO + DAY/NIGHT CYCLE
// =====================================================================
const AudioFX = {
  ctx: null, master: null, ambientGain: null,
  init() {
    if (this.ctx) return;
    try {
      const AC = window.AudioContext || window.webkitAudioContext;
      this.ctx = new AC();
      this.master = this.ctx.createGain(); this.master.gain.value = 0.23;
      this.masterFilter = this.ctx.createBiquadFilter(); this.masterFilter.type = 'lowpass'; this.masterFilter.frequency.value = 22000;
      this.master.connect(this.masterFilter); this.masterFilter.connect(this.ctx.destination);
      this._ambient();
    } catch (e) { this.ctx = null; }
  },
  resume() { this.init(); if (this.ctx && this.ctx.state !== 'running' && this.ctx.state !== 'closed') this.ctx.resume().catch(e => console.warn('Audio resume unavailable', e.message)); },
  setUnderwater(u) { if (this.masterFilter) this.masterFilter.frequency.value = u ? 520 : 22000; },
  _tone(freq, dur, type, gain, slideTo, delay = 0) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + delay;
    const o = this.ctx.createOscillator(), g = this.ctx.createGain();
    o.type = type; o.frequency.setValueAtTime(freq, t);
    if (slideTo) o.frequency.exponentialRampToValueAtTime(Math.max(20, slideTo), t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(this.master); o.start(t); o.stop(t + dur + 0.03);
    o.onended = () => { o.disconnect(); g.disconnect(); };
  },
  _noise(dur, gain, filterFreq, delay = 0) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + delay;      const n = Math.max(1, Math.floor(this.ctx.sampleRate * dur));
    const buf = this.ctx.createBuffer(1, n, this.ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < n; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / n);
    const src = this.ctx.createBufferSource(); src.buffer = buf;
    const f = this.ctx.createBiquadFilter(); f.type = 'bandpass'; f.frequency.value = filterFreq;
    const g = this.ctx.createGain(); g.gain.value = gain;
    src.connect(f); f.connect(g); g.connect(this.master); src.start(t);
    src.onended = () => { src.disconnect(); f.disconnect(); g.disconnect(); };
  },
  _ambient() {
    if (!this.ctx) return;
    this.ambientGain = this.ctx.createGain(); this.ambientGain.gain.value = 0.09;
    const lp = this.ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 320;
    this.ambientGain.connect(lp); lp.connect(this.master);
    for (const fr of [55, 82.5, 110]) {
      const o = this.ctx.createOscillator(); o.type = 'sine'; o.frequency.value = fr;
      const g = this.ctx.createGain(); g.gain.value = 0.12;
      o.connect(g); g.connect(this.ambientGain); o.start();
    }
    // wind layer: looped noise through an LFO-modulated bandpass      const n = Math.floor(this.ctx.sampleRate * 2);
    const buf = this.ctx.createBuffer(1, n, this.ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < n; i++) d[i] = Math.random() * 2 - 1;
    const wind = this.ctx.createBufferSource(); wind.buffer = buf; wind.loop = true;
    const wf = this.ctx.createBiquadFilter(); wf.type = 'bandpass'; wf.frequency.value = 420; wf.Q.value = 0.7;
    const wg = this.ctx.createGain(); wg.gain.value = 0.045;
    const lfo = this.ctx.createOscillator(); lfo.frequency.value = 0.07;
    const lfoGain = this.ctx.createGain(); lfoGain.gain.value = 220;
    lfo.connect(lfoGain); lfoGain.connect(wf.frequency); lfo.start();
    wind.connect(wf); wf.connect(wg); wg.connect(this.master); wind.start();
  },
  play(name) {
    if (!this.ctx || this.ctx.state !== 'running') return;
    this.lastSounds ||= new Map();
    const now = this.ctx.currentTime, last = this.lastSounds.get(name) ?? -10;
    if (now - last < (name === 'step' ? 0.18 : 0.09)) return;
    this.lastSounds.set(name, now);
    switch (name) {
      case 'jump': this._tone(320, 0.16, 'square', 0.16, 520); break;
      case 'land': this._noise(0.16, 0.22, 220); break;
      case 'step': this._noise(0.11, 0.13, 280 + Math.random() * 160); this._tone(120, 0.07, 'sine', 0.1, 78); break;
      case 'heart': this._tone(72, 0.16, 'sine', 0.3, 46); this._tone(58, 0.14, 'sine', 0.22, 40, 0.16); break;
      case 'bow': this._noise(.14,.15,1200);this._tone(200,.12,'triangle',.14,80);break;
      case 'arrowImpact':this._noise(.1,.16,650);this._tone(400,.07,'triangle',.09,180);break;
      case 'swing': this._noise(0.18, 0.16, 900); this._tone(240, 0.12, 'triangle', 0.12, 120); break;
      case 'hit': this._noise(0.12, 0.28, 1600); this._tone(180, 0.12, 'square', 0.16, 90); break;
      case 'hurt': this._tone(200, 0.28, 'sawtooth', 0.22, 90); this._noise(0.2, 0.16, 500); break;
      case 'death': this._tone(180, 1.1, 'sawtooth', 0.28, 55); this._noise(1.0, 0.18, 300); break;
      case 'chop': this._noise(0.14, 0.3, 320); this._tone(140, 0.1, 'triangle', 0.16, 90); break;
      case 'mine': this._noise(0.12, 0.28, 1400); this._tone(260, 0.09, 'square', 0.12, 160); break;
      case 'blade': this._noise(.08,.16,3200); this._tone(450,.09,'triangle',.09,180); break;
      case 'fill': this._noise(.28,.12,500); this._tone(110,.12,'triangle',.05,65); break;
      case 'dig': this._noise(0.16, 0.26, 240); this._tone(110, 0.12, 'triangle', 0.14, 70); break;
      case 'pickup': this._tone(520, 0.12, 'square', 0.12, 760); this._tone(760, 0.12, 'square', 0.1, 1040, 0.08); break;
      case 'eat': this._noise(0.09, 0.22, 900); this._noise(0.09, 0.2, 700, 0.14); this._tone(180, 0.1, 'triangle', 0.1, 120, 0.28); break;
      case 'mob': this._tone(190, 0.18, 'sawtooth', 0.16, 120); break;
      case 'craft': this._tone(320, 0.14, 'square', 0.14, 480); this._tone(480, 0.16, 'triangle', 0.16, 720, 0.12); break;
      case 'huskDie': this._tone(300, 0.35, 'square', 0.2, 80); this._noise(0.3, 0.16, 800); break;
      case 'boss': this._tone(60, 1.8, 'sawtooth', 0.3, 42); this._tone(90, 1.6, 'sawtooth', 0.2, 60, 0.2); this._noise(1.2, 0.16, 180); break;
      case 'thunder': this._noise(1.6, 0.3, 110); this._tone(48, 1.4, 'sine', 0.26, 30); break;
      case 'banish': this._tone(420, 0.8, 'triangle', 0.24, 120); this._noise(0.8, 0.18, 500); break;
      case 'lore': this._tone(520, 0.4, 'sine', 0.18, 780); break;
      case 'empty': this._tone(160, 0.1, 'square', 0.12, 110); break;
    }
  },
};

// ---- day / night ----
const _skyTop = new THREE.Color(), _skyBottom = new THREE.Color(), _fog = new THREE.Color();
const _sd = new THREE.Vector3();
const _white = new THREE.Color(0xffffff);
const _dayTop = new THREE.Color(0x428ac7), _nightTop = new THREE.Color(0x080e20);
const _dayBot = new THREE.Color(0xb4cee0), _nightBot = new THREE.Color(0x182337);
const _duskTop = new THREE.Color(0x7a4a2c), _duskBot = new THREE.Color(0x8a4a2a);
const _stormGray = new THREE.Color(0x596675), _cloudCol = new THREE.Color();
const _waterTint = new THREE.Color(0x1a5c66);
function updateCycle(dt) {
  state.cyclePhase = (state.cyclePhase + dt / CFG.dayLength) % 1;
  const ang = state.cyclePhase * Math.PI * 2;
  const sunHeight = Math.sin(ang);            // -1..1 (1 = noon)
  const daylight = smoothstep(-0.18, 0.32, sunHeight);
  const dusk = Math.max(0, 1 - Math.abs(sunHeight) * 3.2) * (sunHeight > -0.3 ? 1 : 0);

  // sun direction (parallel light); shadow camera follows the player
  _sd.set(Math.cos(ang), Math.max(sunHeight, -0.4), 0.35).normalize();
  sunLight.position.copy(player.pos).addScaledVector(_sd, 150);
  sunLight.target.position.copy(player.pos);
  sunLight.target.updateMatrixWorld();
  const storm = weather.intensity * (weather.type === 'storm' ? 1 : weather.type === 'rain' ? 0.55 : 0.35);
  sunLight.intensity = (0.15 + daylight * 1.25) * (1 - storm * 0.55);
  if (daylight < 0.15) sunLight.color.setHex(0xa9bbd6);
  if (daylight >= 0.15) sunLight.color.setHSL(0.11 - dusk * 0.055, 0.32 + dusk * 0.35, 0.65 + daylight * 0.1);
  ambientLight.intensity = (0.22 + daylight * 0.5) * (1 - storm * 0.3);
  hemiLight.intensity = (0.3 + daylight * 0.55) * (1 - storm * 0.35);
  state.night = daylight < 0.28;

  // cinematic grade: warm exposure at day/dusk, sun disc + halo in the sky dome
  renderer.toneMappingExposure = 0.92 + daylight * 0.22 + dusk * 0.14;
  skyMat.uniforms.sunDir.value.copy(_sd);
  skyMat.uniforms.sunColor.value.copy(sunLight.color).lerp(_white, 0.3);
  skyMat.uniforms.sunGlow.value = 0.22 + daylight * 0.9 + dusk * 0.6;

  // sky colors
  _skyTop.copy(_nightTop).lerp(_dayTop, daylight);
  _skyBottom.copy(_nightBot).lerp(_dayBot, daylight);
  if (dusk > 0) {
    _skyTop.lerp(_duskTop, dusk * 0.5);
    _skyBottom.lerp(_duskBot, dusk * 0.6);
  }
  if (storm > 0) {
    _skyTop.lerp(_stormGray, storm * 0.7);
    _skyBottom.lerp(_stormGray, storm * 0.55);
  }
  _cloudCol.copy(_white).lerp(_nightTop, (1 - daylight) * 0.72).lerp(_stormGray, storm * 0.8);
  cloudMat.color.copy(_cloudCol);
  cloudMat.opacity = 0.86 - storm * 0.22;
  skyMat.uniforms.topColor.value.copy(_skyTop);
  skyMat.uniforms.bottomColor.value.copy(_skyBottom);
  _fog.copy(_skyBottom).multiplyScalar(1.05);
  scene.fog.color.copy(_fog);
  starMat.opacity = clamp(1 - daylight * 1.25, 0, 0.9);
  waterMat.color.copy(_skyBottom).lerp(_waterTint, 0.5);
  // glowing fog banks breathe slowly
  MAT.fogBank.opacity = 0.055 + Math.sin(state.time * 0.35) * 0.015;
}

// =====================================================================
// S6b · WEATHER · CLOUDS
// =====================================================================
const WEATHER_LABEL = { clear: 'CLEAR', rain: 'RAIN', storm: 'THUNDERSTORM', snow: 'SNOW' };
const weather = {
  type: 'clear', next: 'clear',
  intensity: 0,            // 0..1, smoothed transition between types
  timer: 55,               // seconds until the next weather roll (random, not a fixed cycle)
  lightningTimer: 4,
};
function pickWeather() {
  const r = Math.random();
  return r < 0.38 ? 'clear' : r < 0.65 ? 'rain' : r < 0.8 ? 'storm' : 'snow';
}
function updateWeather(dt) {
  weather.timer -= dt;
  if (weather.timer <= 0) {
    weather.timer = 75 + Math.random() * 110;      // random hold duration
    weather.next = pickWeather();
  }
  if (weather.type !== weather.next) {
    weather.intensity = Math.max(0, weather.intensity - dt * 0.22);   // fade the old out
    if (weather.intensity <= 0) weather.type = weather.next;
  } else {
    weather.intensity = Math.min(1, weather.intensity + dt * 0.22);   // fade the new in
  }
  // lightning during storms
  if (weather.type === 'storm' && weather.intensity > 0.5) {
    weather.lightningTimer -= dt;
    if (weather.lightningTimer <= 0) {
      weather.lightningTimer = 3 + Math.random() * 9;
      state.flash = 0.7 + Math.random() * 0.5;
      AudioFX.play('thunder');
    }
  }
}

// ---- rain / snow particle field (follows the player) ----
const WEATHER_MAX = 2400;
const wGeo = new THREE.BufferGeometry();
const wPos = new Float32Array(WEATHER_MAX * 3);
const wVel = new Float32Array(WEATHER_MAX);
for (let i = 0; i < WEATHER_MAX; i++) {
  wPos[i*3] = (Math.random() - 0.5) * 72;
  wPos[i*3+1] = Math.random() * 34 - 4;
  wPos[i*3+2] = (Math.random() - 0.5) * 72;
  wVel[i] = 0.75 + Math.random() * 0.5;
}
wGeo.setAttribute('position', new THREE.BufferAttribute(wPos, 3));
const wMat = new THREE.PointsMaterial({ color: 0x9db8cc, size: 0.13, transparent: true, opacity: 0, depthWrite: false });
const weatherPoints = new THREE.Points(wGeo, wMat);
weatherPoints.frustumCulled = false;
scene.add(weatherPoints);

function updateWeatherParticles(dt) {
  const w = weather.intensity;
  const snowing = weather.type === 'snow';
  const active = (weather.type === 'rain' || weather.type === 'storm' || snowing) ? w : 0;
  wMat.opacity = active * (snowing ? 0.9 : 0.55);
  wMat.color.setHex(snowing ? 0xffffff : 0x9db8cc);
  wMat.size = snowing ? 0.22 : 0.13;
  const count = Math.floor(WEATHER_MAX * active);
  wGeo.setDrawRange(0, count);
  if (!count) return;
  const arr = wGeo.attributes.position.array;
  const cx = player.pos.x, cz = player.pos.z;
  const fall = snowing ? 2.4 : 24;
  for (let i = 0; i < count; i++) {
    arr[i*3+1] -= fall * wVel[i] * dt;
    if (snowing) arr[i*3] += Math.sin(state.time * 1.3 + i) * dt * 1.2;
    if (arr[i*3+1] < -4) {
      arr[i*3+1] = 30 + Math.random() * 6;
      arr[i*3] = cx + (Math.random() - 0.5) * 72;
      arr[i*3+2] = cz + (Math.random() - 0.5) * 72;
    }
    // wrap the field around the player
    if (arr[i*3] > cx + 37) arr[i*3] -= 74; else if (arr[i*3] < cx - 37) arr[i*3] += 74;
    if (arr[i*3+2] > cz + 37) arr[i*3+2] -= 74; else if (arr[i*3+2] < cz - 37) arr[i*3+2] += 74;
  }
  wGeo.attributes.position.needsUpdate = true;
}

// ---- soft drifting clouds (billboard puffs, like a big-sky fantasy world) ----
const CLOUD_COUNT = 64;
const cloudMat = new THREE.SpriteMaterial({ map: TEX.glow, color: 0xffffff, transparent: true, opacity: 0.75, depthWrite: false });
const cloudData = [];
for (let i = 0; i < CLOUD_COUNT; i++) {
  const spr = new THREE.Sprite(cloudMat);
  const s = 30 + Math.random() * 46;
  spr.scale.set(s, s * 0.34, 1);
  spr.position.set((Math.random() - 0.5) * 380, 58 + Math.random() * 26, (Math.random() - 0.5) * 380);
  cloudData.push(spr);
  scene.add(spr);
}
function updateClouds(dt) {
  for (const c of cloudData) {
    c.position.x += dt * 1.5;
    if (c.position.x > player.pos.x + 200) c.position.x -= 400;
    else if (c.position.x < player.pos.x - 200) c.position.x += 400;
    if (c.position.z > player.pos.z + 200) c.position.z -= 400;
    else if (c.position.z < player.pos.z - 200) c.position.z += 400;
  }
}

// =====================================================================
// S7 · HUD · MINIMAP · MAIN LOOP · INPUT BINDINGS · INIT/RESET
// =====================================================================
// ---- god-ray screen overlay tracking the sun's projected position ----
const _sunScreen = new THREE.Vector3();
function updateGodRays() {
  const el = dom.godrays;
  if (!Q.godrays || underwaterAt(camera.position.x, camera.position.y, camera.position.z)) { el.style.opacity = '0'; return; }
  const sunDir = skyMat.uniforms.sunDir.value;
  _sunScreen.copy(sunDir).multiplyScalar(500).add(camera.position);
  _sunScreen.project(camera);
  if (_sunScreen.z > 1 || _sunScreen.z < -1) { el.style.opacity = '0'; return; }   // sun behind camera
  const elev = smoothstep(0.0, 0.24, sunDir.y);
  const dx = _sunScreen.x * 0.5 * window.innerWidth;
  const dy = -_sunScreen.y * 0.5 * window.innerHeight;
  el.style.transform = `translate(calc(-50% + ${dx.toFixed(1)}px), calc(-50% + ${dy.toFixed(1)}px))`;
  el.style.opacity = String(clamp(elev * 0.8, 0, 0.8));
}

function updateHUD() {
  updateVitals();
  dom.resWood.textContent = state.inv.wood;
  dom.resStone.textContent = state.inv.stone;
  dom.resGold.textContent = state.inv.gold;
  dom.resIron.textContent = state.inv.iron;
  dom.resBerries.textContent = state.inv.berries;
  dom.resMeat.textContent = state.inv.meat;
  $('res-soil').textContent=state.inv.soil||0;
  dom.telCoord.textContent = Math.round(player.pos.x) + ', ' + Math.round(player.pos.z);
  dom.sectorCoord.textContent = Math.floor(player.pos.x / CFG.chunkSize) + ',' + Math.floor(player.pos.z / CFG.chunkSize);
  const tod = state.night ? 'NIGHT' : (state.cyclePhase < 0.42 ? 'DAY' : 'DUSK');
  dom.statusDay.textContent = 'DAY ' + (state.days + 1) + ' \u00b7 ' + tod;
  dom.telWeather.textContent = WEATHER_LABEL[weather.type];

  let threat = 'DORMANT', danger = 0;
  const t = world.tomPearl;
  if (t && t.alive!==false) {
    const d = dist2D(player.pos.x, player.pos.z, t.group.position.x, t.group.position.z);
    if (d < 6) { threat = 'TOUCHING'; danger = 0.85; }
    else if (d < 16) { threat = 'CLOSE'; danger = 0.5; }
    else if (d < 34) { threat = 'HUNTING'; danger = 0.22; }
    else { threat = 'WALKING'; danger = 0; }
    danger = Math.max(danger, clamp(1 - d / 22, 0, 0.85));
  }
  dom.telThreat.textContent = threat;
  dom.telThreat.className = 'v ' + (threat === 'DORMANT' ? '' : 'bad');
  dom.dangerVignette.style.opacity = String(state.paused || state.dead ? 0 : danger);
  state.danger = danger;

  // underwater effect (eye below the water surface)
  const under = underwaterAt(camera.position.x, camera.position.y, camera.position.z);
  dom.underwater.style.opacity = under && !state.dead && !state.paused ? '1' : '0';
  AudioFX.setUnderwater(under);
  if (under) {
    scene.fog.density = 0.05;
    scene.fog.color.setHex(0x0d4a66);
    waterMat.opacity = 0.9;
  } else {
    scene.fog.density = 0.012 + weather.intensity * (weather.type === 'storm' ? 0.016 : 0.009);
    waterMat.opacity = 0.72;
  }
}

function drawMinimap() {
  const cvs = dom.minimap, ctx = cvs.getContext('2d');
  const w = cvs.width, h = cvs.height, cx = w / 2, cy = h / 2;
  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = '#101923'; ctx.fillRect(0, 0, w, h);
  ctx.save();
  ctx.beginPath(); ctx.arc(cx, cy, cx - 2, 0, Math.PI * 2); ctx.clip();
  const s = (cx - 6) / 62;   // pixels per world unit (~62u radius)
  const toMap = (x, z) => ({ x: cx + (x - player.pos.x) * s, y: cy + (z - player.pos.z) * s });
  const dot = (x, z, color, r) => {
    const p = toMap(x, z);
    if (p.x < -20 || p.x > w + 20 || p.y < -20 || p.y > h + 20) return;
    ctx.fillStyle = color; ctx.beginPath(); ctx.arc(p.x, p.y, r, 0, Math.PI * 2); ctx.fill();
  };
  for (const h of world.harvestables) {
    if (h.dead || h.hidden) continue;
    dot(h.x, h.z, h.type === 'rock' ? '#8a8a84' : '#7c5c34', 1.7);
  }
  for (const m of world.mobs) if (m.alive) dot(m.group.position.x, m.group.position.z, '#e0e0e0', 2.6);
  for (const e of world.husks) if (e.alive) dot(e.group.position.x, e.group.position.z, '#ff7a3a', 3);
  if (world.tomPearl) dot(world.tomPearl.group.position.x, world.tomPearl.group.position.z, '#ff3030', 4.5);
  survival.minimapExtras(ctx, toMap);
  // player arrow
  ctx.save();
  ctx.translate(cx, cy); ctx.rotate(-player.yaw);
  ctx.fillStyle = '#e8d7b3';
  ctx.beginPath(); ctx.moveTo(0, -7); ctx.lineTo(5, 6); ctx.lineTo(0, 3); ctx.lineTo(-5, 6); ctx.closePath(); ctx.fill();
  ctx.restore();
  ctx.restore();
  // border ring
  ctx.strokeStyle = 'rgba(213,191,152,0.35)'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.arc(cx, cy, cx - 2, 0, Math.PI * 2); ctx.stroke();
}

// =====================================================================
// S5c · VOXEL MOBS (PASSIVE ANIMALS) · FOOD
// =====================================================================
function buildSmoothAnimal(kind) {
  const group = new THREE.Group();
  const isPig = kind === 'pig';
  const mat = new THREE.MeshStandardMaterial({ color: isPig ? 0xe8a0a8 : 0xa9744c, roughness: 0.85 });
  const matDark = new THREE.MeshStandardMaterial({ color: isPig ? 0xc97f8c : 0x7c5232, roughness: 0.85 });
  // rounded body
  const body = new THREE.Mesh(new THREE.CapsuleGeometry(0.55, 1.1, 12, 20), mat);
  body.rotation.z = Math.PI / 2;
  body.position.y = 1.05;
  body.scale.set(1, 1, 0.82);
  group.add(body);
  // head + snout
  const head = new THREE.Mesh(new THREE.SphereGeometry(0.42, 24, 18), mat);
  head.position.set(1.05, 1.35, 0);
  head.scale.set(1, 0.95, 0.9);
  group.add(head);
  const snout = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.24, 0.3, 16, 4), matDark);
  snout.rotation.z = -Math.PI / 2;
  snout.position.set(1.45, 1.22, 0);
  group.add(snout);
  // ears
  for (const side of [-1, 1]) {
    const ear = new THREE.Mesh(new THREE.ConeGeometry(0.14, 0.34, 12, 4), matDark);
    ear.position.set(0.92, 1.78, side * 0.22);
    ear.rotation.x = side * 0.35;
    group.add(ear);
  }
  // tail
  const tail = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.09, 0.6, 10, 3), matDark);
  tail.position.set(-1.25, 1.25, 0);
  tail.rotation.z = 0.9;
  group.add(tail);
  // legs (pivots for walk swing)
  const legs = [];
  for (const [sx, sz] of [[0.62, 0.3], [0.62, -0.3], [-0.62, 0.3], [-0.62, -0.3]]) {
    const pivot = new THREE.Group();
    pivot.position.set(sx, 0.92, sz);
    const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.11, 0.9, 12, 4), matDark);
    leg.position.y = -0.42;
    pivot.add(leg);
    group.add(pivot);
    legs.push(pivot);
  }
  return { group, head, legs, mats: [mat, matDark] };
}

function spawnMob(x, z, kind) {
  const built = ART.animal(kind) || buildSmoothAnimal(kind);
  built.group.position.set(x, terrainHeight(x, z), z);
  scene.add(built.group);
  world.mobs.push({ ...built, kind, hp: 10, speed: 2.1 + Math.random() * 0.8,
    walkPhase: Math.random() * 6, alive: true, deathT: 0,
    dir: Math.random() * Math.PI * 2, turnT: 2 + Math.random() * 4,
    flee: 0, idleT: Math.random() * 3 });
}

function updateMobs(dt) {
  if (state.paused) return;
  const p = player.pos;
  for (let i = world.mobs.length - 1; i >= 0; i--) {
    const m = world.mobs[i];
    if (!m.alive) {
      if(deathSystem.updateDeath(m,dt))world.mobs.splice(i,1);
      continue;
    }
    const dx = p.x - m.group.position.x, dz = p.z - m.group.position.z;
    const d = Math.hypot(dx, dz);
    m.flee = Math.max(0, m.flee - dt);
    let speed = 0;
    if (m.flee > 0 && d < 26) {
      m.dir += Math.sin(state.time * 1.4 + m.walkPhase * 0.05) * dt * 0.12; // stable escape heading
      speed = m.speed * 2.3;
    } else {
      m.turnT -= dt; m.idleT -= dt;
      if (m.idleT <= 0) {
        speed = m.speed * 0.55;
        if (m.turnT <= 0) {
          m.turnT = 2.5 + Math.random() * 5;
          m.idleT = Math.random() < 0.35 ? 1.5 + Math.random() * 2.5 : 0;
          m.dir += (Math.random() - 0.5) * 2.2;
        }
      }
    }
    const nx = m.group.position.x + Math.sin(m.dir) * speed * dt;
    const nz = m.group.position.z + Math.cos(m.dir) * speed * dt;
    const blocked = world.colliders.some(c => Math.hypot(nx - c.x, nz - c.z) < c.r + 0.7);
    if (!waterColumnAt(nx, nz) && !blocked && Math.abs(terrainHeight(nx, nz) - m.group.position.y) < 0.65) {
      m.group.position.x = nx; m.group.position.z = nz;
    } else {
      m.dir += dt * 3.5; // steer around obstacles rather than flip every frame
    }
    m.group.position.y = terrainHeight(m.group.position.x, m.group.position.z);
    m.group.rotation.y = m.dir - Math.PI / 2; // animal model faces +X, not +Z
    // legs swing while moving, head glances around
    m.walkPhase += dt * speed * 2.4;
    const sw = speed > 0.1 ? Math.sin(m.walkPhase) : 0;
    for (let li = 0; li < m.legs.length; li++) m.legs[li].rotation.x = sw * (li % 2 === 0 ? 0.75 : -0.75);
    if (!m.mixer) m.head.rotation.y = Math.sin(state.time * 0.6 + m.walkPhase) * 0.28;
    ART.animateAnimal(m,dt,speed);
    resolveCollision(m.group.position,.55); resolveBuildCollision(m.group.position,.55);
    // keep the herd near the player
    if (d > 90) {
      const a = Math.random() * Math.PI * 2, r = 30 + Math.random() * 20;
      m.group.position.set(p.x + Math.cos(a) * r, 0, p.z + Math.sin(a) * r);
      m.group.position.y = terrainHeight(m.group.position.x, m.group.position.z);
    }
  }
}

function hurtMob(m, dmg) {
  if (!m.alive) return;
  m.hp -= dmg;
  m.flee = 6; m.reaction = .3;
  impactFeedback(m);
  m.dir = Math.atan2(m.group.position.x - player.pos.x, m.group.position.z - player.pos.z);
  m.walkPhase += 1.5;
  const dx = m.group.position.x - player.pos.x, dz = m.group.position.z - player.pos.z;
  const d = Math.hypot(dx, dz) || 1;
  m.group.position.x += (dx / d) * 1.1;
  m.group.position.z += (dz / d) * 1.1;
  AudioFX.play('mob');
  if (m.hp <= 0) {
    deathSystem.beginDeath(m,'animal',{meat:2+Math.floor(Math.random()*2),hide:m.kind==='deer'?3:2});
  }
}

let mobTimer = 6;
function updateMobSpawner(dt) {
  if (!state.started || state.dead || state.paused) return;
  mobTimer -= dt;
  if (mobTimer > 0) return;
  mobTimer = 11 + Math.random() * 9;
  if (world.mobs.filter((m) => m.alive).length >= 6) return;
  const a = Math.random() * Math.PI * 2, r = 22 + Math.random() * 16;
  const x = player.pos.x + Math.cos(a) * r, z = player.pos.z + Math.sin(a) * r;
  const h = terrainHeight(x, z);
  if (h > CFG.waterLevel + 0.5 && h < 16) {
    spawnMob(x, z, Math.random() < 0.5 ? 'pig' : 'deer');
  }
}

// ---- hunger + food ----
function updateHunger(dt) {
  const moving = Math.hypot(player.vel.x, player.vel.z) > 1;
  const drain = 0.16 + (moving ? 0.22 : 0) + (input.sprint && moving ? 0.8 : 0);
  state.hunger = clamp(state.hunger - dt * drain, 0, 100);
  if (state.hunger > 65 && state.hp < 100) {
    state.hp = clamp(state.hp + dt * 1.8, 0, 100);
    state.hunger = clamp(state.hunger - dt * 0.35, 0, 100);
  } else if (state.hunger <= 0) {
    state.hp = clamp(state.hp - dt * 1.1, 0, 100);
    if (state.hp <= 0) die('STARVATION TOOK YOU');
  }
}
function eatFood() {
  if (!state.started || state.dead || state.paused) return;
  if(inventoryUI.use())return;
  if (state.hunger >= 98 && state.hp >= 100) { showToast('NOT HUNGRY', 1400); return; }
  if ((state.inv.cooked || 0) > 0) {
    state.inv.cooked--; state.hunger = clamp(state.hunger+55,0,100); state.hp = clamp(state.hp+14,0,100);
    showToast('ATE <b>COOKED MEAT</b> · +55 FOOD / +14 HEALTH',1800); AudioFX.play('eat');
  } else if (state.inv.meat > 0 && (state.hunger < 55 || state.inv.berries === 0)) {
    state.inv.meat--;
    state.hunger = clamp(state.hunger + 18, 0, 100);
    state.hp = clamp(state.hp + 1, 0, 100);
    showToast('ATE <b>RAW MEAT</b> · +18 FOOD · COOK AT A CAMPFIRE FOR MORE', 1800);
    AudioFX.play('eat');
  } else if (state.inv.berries > 0) {
    state.inv.berries--;
    state.hunger = clamp(state.hunger + 12, 0, 100);
    state.hp = clamp(state.hp + 2, 0, 100);
    showToast('ATE <b>BERRIES</b>  ·  +12 HUNGER', 1800);
    AudioFX.play('eat');
  } else {
    showToast('NO FOOD · PICK <b>BERRIES</b> OR KILL AN ANIMAL FOR MEAT', 1800);
  }
}

// ---- swimming + breath ----
function updateBreath(dt) {
  const eyeUnder = underwaterAt(camera.position.x, camera.position.y, camera.position.z);
  if (eyeUnder) {
    state.breath = clamp(state.breath - dt * 8, 0, 100);   // ~12s of air
    if (state.breath <= 0) {
      state.drownT -= dt;
      if (state.drownT <= 0) {
        state.drownT = 1.15;
        damagePlayer(4, 'YOU DROWNED');
      }
    }
  } else if (state.breath < 100) {
    state.breath = clamp(state.breath + dt * 42, 0, 100);
    state.drownT = 0;
  }
}

// ---- digging + ore veins ----
function pickDigPoint() {    const dir = new THREE.Vector3();camera.getWorldDirection(dir);
  const p = camera.position.clone();
  for (let i = 0; i < Math.ceil(activeWeapon().reach/.25); i++) {
    p.addScaledVector(dir, 0.25);
    if (p.y <= groundHeightAt(p.x, p.z) + 0.1) return { x: p.x, z: p.z };
  }
  return null;
}
const SCOOP_RADIUS=1.65,SCOOP_DEPTH=.24,MAX_DIG_DEPTH=2.4;
function terrainEditReason(pt,fill=false){
  if(!pt)return 'Aim at dry ground within shovel reach';
  const {x,z}=pt,r=SCOOP_RADIUS;
  if(Math.hypot(x-camera.position.x,z-camera.position.z)>activeWeapon().reach)return 'Ground is out of reach';
  if(dist2D(x,z,player.pos.x,player.pos.z)<r+.25)return 'Step away · do not excavate under your feet';
  const h=terrainHeight(x,z);
  if(baseHeight(x,z)<CFG.waterLevel+1||h<CFG.waterLevel+.4)return 'Shoreline is protected';
  if(world.caves.some(c=>dist2D(x,z,c.x,c.z)<c.r+2))return 'Cave roof / survey entrance is protected';
  if(world.colliders.some(c=>c.minY===undefined&&dist2D(x,z,c.x,c.z)<r+c.r+.2))return 'Clear the tree or rock first';
  if(world.harvestables.some(q=>!q.dead&&q.type==='bush'&&dist2D(x,z,q.x,q.z)<r+.4))return 'Harvest this patch first';
  if(world.structures.some(s=>dist2D(x,z,s.x,s.z)<r+2.3)||world.pois.some(p=>dist2D(x,z,p.x,p.z)<r+3))return 'Foundation / landmark is protected';
  if(world.torches.some(t=>dist2D(x,z,t.group.position.x,t.group.position.z)<r+.4))return 'Dismantle the torch first';
  if(!fill){
    const samples=[{x,z},...world.digs.filter(d=>dist2D(d.x,d.z,x,z)<r).map(d=>({x:d.x,z:d.z}))];
    for(let dx=-r;dx<=r;dx+=.4)for(let dz=-r;dz<=r;dz+=.4)if(Math.hypot(dx,dz)<r)samples.push({x:x+dx,z:z+dz});
    for(const q of samples){const t=1-dist2D(q.x,q.z,x,z)/r;if(-digOffset(q.x,q.z)+SCOOP_DEPTH*t*t*(3-2*t)>MAX_DIG_DEPTH+.001)return 'Bedrock reached · maximum excavation 2.4m';}
    for(let i=0;i<9;i++){const a=i*Math.PI/4,rr=i===8?0:.8,xx=x+Math.cos(a)*rr,zz=z+Math.sin(a)*rr;
      if(Math.max(Math.abs(terrainHeight(xx+.5,zz)-terrainHeight(xx-.5,zz)),Math.abs(terrainHeight(xx,zz+.5)-terrainHeight(xx,zz-.5)))>1.2)return 'Ground is too steep';
    }
    if(world.digs.length>=2000)return 'Terrain edit limit reached · refill an existing scoop';
  }
  return '';
}
function digGround(pt,w){
  if(!w.shovel||!state.crafted.has(w.id)||state.dead||state.paused)return false;
  const reason=terrainEditReason(pt);if(reason){showToast(reason,1700);return false;}
  if(!addDig(pt.x,pt.z,SCOOP_RADIUS,SCOOP_DEPTH,1))return false;
  state.inv.soil=(state.inv.soil||0)+1;remeshNear(pt.x,pt.z,SCOOP_RADIUS+.2);updateOreNodes();
  spawnBurst(new THREE.Vector3(pt.x,terrainHeight(pt.x,pt.z)+.25,pt.z),0x82654a);AudioFX.play('dig');flashHitmarker();
  showToast('+1 SOIL · V / right click refills one scoop',1600);survival.saveGame(false);return true;
}
function fillGround(pt){
  const w=activeWeapon();
  if(!playable()||!w.shovel||!state.crafted.has(w.id)||state.toolCooldown>0||findCombatTarget()||findHarvestTarget())return false;
  const reason=terrainEditReason(pt,true);if(reason){showToast(reason,1700);return false;}
  const d=[...world.digs].reverse().find(q=>dist2D(q.x,q.z,pt.x,pt.z)<q.r*.8);
  if(!d){showToast('No excavated soil here · cannot raise untouched ground',1600);return false;}
  if((state.inv.soil||0)<1){showToast('Need 1 soil to refill a scoop',1500);return false;}
  if(state.stamina<6){showToast('Catch your breath',1500);return false;}
  state.inv.soil--;state.stamina-=6;state.toolCooldown=w.cooldown;toolSwing=1;
  if(d.soilUnits===1||d.depth<=SCOOP_DEPTH)world.digs.splice(world.digs.indexOf(d),1);else d.depth-=SCOOP_DEPTH;
  reindexDigs();remeshNear(d.x,d.z,d.r+.2);updateOreNodes();
  spawnBurst(new THREE.Vector3(pt.x,terrainHeight(pt.x,pt.z)+.2,pt.z),0x947651);AudioFX.play('fill');showToast('Filled one scoop · −1 soil',1500);survival.saveGame(false);return true;
}  const shovelPreviewPoints=new Float32Array(32*3),shovelPreviewGeometry=new THREE.BufferGeometry();shovelPreviewGeometry.setAttribute('position',new THREE.BufferAttribute(shovelPreviewPoints,3));
const shovelPreview=new THREE.LineLoop(shovelPreviewGeometry,new THREE.LineBasicMaterial({color:0xc4a574,transparent:true,opacity:.7,depthWrite:false}));scene.add(shovelPreview);
let shovelPreviewClock=0;
function updateShovelPreview(){
  if(playable()&&activeWeapon().shovel&&state.time<shovelPreviewClock)return;
  shovelPreviewClock=state.time+.08;
  shovelPreview.visible=false;if(!playable()||!activeWeapon().shovel||findCombatTarget()||findHarvestTarget())return;
  const pt=pickDigPoint();if(!pt)return;
  for(let i=0;i<32;i++){const a=i/32*Math.PI*2,x=pt.x+Math.cos(a)*SCOOP_RADIUS,z=pt.z+Math.sin(a)*SCOOP_RADIUS;shovelPreviewPoints[i*3]=x;shovelPreviewPoints[i*3+1]=terrainHeight(x,z)+.04;shovelPreviewPoints[i*3+2]=z;}
  shovelPreviewGeometry.attributes.position.needsUpdate=true;shovelPreviewGeometry.computeBoundingSphere();shovelPreview.material.color.setHex(terrainEditReason(pt)?0xc17566:0xc4a574);shovelPreview.visible=true;
}
function updateOreNodes() {
  for (const d of world.chunks.values()) {
    for (const h of d.harvest) {
      if (h.type !== 'ore' || h.dead || !h.hidden) continue;
      if (terrainHeight(h.x, h.z) < h.y + .6) {
        h.hidden = false;
        if(h.id)world.harvestState.set(h.id,{hp:h.hp,dead:h.dead,hidden:false});
        h.group.visible = true;
        world.oreShown.add(hkey(h.x, h.z));
        showToast('ORE VEIN <b>EXPOSED</b>!', 2600);
        AudioFX.play('pickup');
      }
    }
  }
}

// =====================================================================
// S5d · LIGHT POOL · CAVES · TORCHES · CAVE CRAWLERS
// =====================================================================
// ---- pooled point lights (permanently in the scene; no shader recompiles) ----
const LIGHT_POOL = [];
for (let i = 0; i < 6; i++) {
  const l = new THREE.PointLight(0xffb26a, 0, 18, 2);
  l.position.set(0, -999, 0);
  scene.add(l);
  LIGHT_POOL.push({ light: l, busy: false, base: 0, flicker: 0 });
}
function allocLight(color, intensity, distance, flicker = 0) {
  for (const slot of LIGHT_POOL) {
    if (!slot.busy) {
      slot.busy = true;
      slot.base = intensity;
      slot.flicker = flicker;
      slot.light.color.setHex(color);
      slot.light.intensity = intensity;
      slot.light.distance = distance;
      return slot;
    }
  }
  return null;                       // pool exhausted: geometry remains emissive instead of adding unbounded lights
}
function freeLight(slot) {
  if (!slot) return;
  slot.busy = false;
  slot.base = 0;
  slot.flicker = 0;
  slot.light.intensity = 0;
  slot.light.position.set(0, -999, 0);
}
function updateLightFlicker() {
  const ranked=world.torches.map(t=>({t,d:t.group.position.distanceTo(camera.position)})).sort((a,b)=>a.d-b.d);
  for(const {t,d}of ranked){
    if(d>26&&t.light){freeLight(t.light);t.light=null;}
  }
  for(const {t,d}of ranked){if(d<26&&!t.light){t.light=allocLight(0xffb26a,2.6,22,.55);if(t.light)t.light.light.position.copy(t.group.position).add(new THREE.Vector3(0,1.25,0));}}
  for (const slot of LIGHT_POOL) {
    if (!slot.busy) continue;
    if (slot.base <= 0) { slot.light.intensity = 0; continue; }   // switched off (e.g. torch stowed)
    if (slot.flicker <= 0) { slot.light.intensity = slot.base; continue; }
    slot.light.intensity = slot.base * (1 + Math.sin(state.time * 9 + slot.light.position.x * 1.7) * slot.flicker);
  }
}
// warm light carried while a torch is selected
const heldLight = allocLight(0xffb26a, 0, 16, 0.5);

// ---- torch placement ----
const TORCH_WOOD_MAT = new THREE.MeshStandardMaterial({ color: 0x6b4a22, roughness: 0.85 });
const TORCH_FLAME_MAT = new THREE.MeshStandardMaterial({ color: 0xffc24a, emissive: 0xff9a2a, emissiveIntensity: 2.4, roughness: 0.4 });
const TORCH_HALO_MAT = new THREE.SpriteMaterial({ map: TEX.glow, color: 0xffc24a, transparent: true, opacity: 0.5, depthWrite: false, blending: THREE.AdditiveBlending });
function placeTorch(pt, restoring = false) {
  if(!pt||![pt.x,pt.z].every(Number.isFinite))return false;
  if(world.torches.length>=8){showToast('8 torches placed · aim at one and X to recover it',2000);return false;}
  if(!restoring){
    if(state.dead||state.paused||!state.crafted.has('torch'))return false;
    if(world.torches.some(t=>dist2D(pt.x,pt.z,t.group.position.x,t.group.position.z)<.55)){showToast('Torch already occupies this spot',1500);return false;}
    if(state.inv.wood<1){showToast('Need 1 wood to place a torch',1800);return false;}state.inv.wood--;
  }
  const g = new THREE.Group();
  const stick = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.07, 1.15, 8, 3), TORCH_WOOD_MAT);
  stick.position.y = 0.55;
  const flame = new THREE.Mesh(new THREE.SphereGeometry(0.15, 12, 10), TORCH_FLAME_MAT);
  flame.position.y = 1.16;
  const halo = new THREE.Sprite(TORCH_HALO_MAT);
  halo.scale.setScalar(1.9);
  halo.position.y = 1.16;
  const model=ART.instance('torch',1.22);
  if(model){stick.geometry.dispose();flame.geometry.dispose();g.add(model,halo);}else g.add(stick,flame,halo);
  const y = restoring && Number.isFinite(pt.y) ? pt.y : groundHeightAt(pt.x, pt.z);
  g.position.set(pt.x, y, pt.z);
  g.rotation.y = Math.random() * Math.PI * 2;
  scene.add(g);
  const light = dist2D(pt.x,pt.z,player.pos.x,player.pos.z)<26 ? allocLight(0xffb26a, 2.6, 22, 0.55) : null;
  if (light) light.light.position.set(pt.x, y + 1.25, pt.z);
  world.torches.push({ group: g, light });
  if(!restoring){AudioFX.play('craft');showToast('Torch placed · X recovers 1 wood',1500);survival.saveGame(false);}return true;
}

const torchRay=new THREE.Raycaster();
function aimedTorch(){
  const dir=new THREE.Vector3();camera.getWorldDirection(dir);torchRay.set(camera.position,dir);torchRay.camera=camera;torchRay.far=4.2;camera.updateMatrixWorld(true);
  let best=null,distance=Infinity;
  for(const t of world.torches){t.group.updateMatrixWorld(true);const hits=torchRay.intersectObject(t.group,true).filter(h=>h.object.isMesh);if(hits[0]&&hits[0].distance<distance){best=t;distance=hits[0].distance;}}
  if(!best)return null;
  const obstruction=torchRay.intersectObjects([...world.harvestables.filter(h=>!h.dead&&!h.hidden).map(h=>h.group),...(world.structures||[]).map(s=>s.group)],true)[0];
  return obstruction&&obstruction.distance<distance-.05?null:best;
}
function removeTorch(t,refund=false){
  const i=world.torches.indexOf(t);if(i<0)return false;
  t.group.removeFromParent();t.group.traverse(o=>{if(o.geometry&&!SHARED_GEOMS.has(o.geometry))o.geometry.dispose();});freeLight(t.light);t.light=null;world.torches.splice(i,1);
  if(refund)state.inv.wood++;return true;
}
function dismantleTorch(){const t=aimedTorch();if(!t)return false;removeTorch(t,true);AudioFX.play('chop');showToast('Torch recovered · +1 wood',1500);survival.saveGame(false);return true;}

// ---- cave sites (large underground chambers, streamed near the player) ----
const CAVE_CELL = 150;
function caveSiteAt(i, j) {
  const rng = mulberry32((i * 374761393) ^ (j * 668265263) ^ (CFG.seed ^ 0xCAFE));
  const x = i * CAVE_CELL + 30 + rng() * 90;
  const z = j * CAVE_CELL + 30 + rng() * 90;
  const surf = terrainHeight(x, z) - digOffset(x, z);
  if (surf < CFG.waterLevel + 1) return null;        // no caves under the sea
  return {
    i, j, x, z,
    y: surf - (11 + rng() * 6),
    r: 9 + rng() * 5,
    breached: CFG.terrainVersion===2, entranceX:x, entranceZ:z-(9+rng()*3),
    dome: null, light: null, colliders: [], harvest: [], mobTimer: 2 + rng() * 4, mobs: 0,
  };
}
function buildCaveMeshes(c) {
  const g = new THREE.Group();
  const caveMat = new THREE.MeshStandardMaterial({ map: TEX.rock, color: 0x8a8478, roughness: 1.0, side: THREE.BackSide });
  // floor: gently domed disc
  const floorGeo = new THREE.CircleGeometry(c.r + 1, 28);
  floorGeo.rotateX(-Math.PI / 2);
  const fp = floorGeo.attributes.position;
  for (let i = 0; i < fp.count; i++) {
    const d = Math.hypot(fp.getX(i), fp.getZ(i)) / (c.r + 1);
    fp.setY(i, Math.sin(d * Math.PI) * -0.9);
  }
  floorGeo.computeVertexNormals();
  const floor = new THREE.Mesh(floorGeo, MAT.rock);
  floor.position.set(c.x, c.y, c.z);
  floor.receiveShadow = true;
  g.add(floor);
  // ceiling dome + walls (BackSide: seen from inside)
  const dome = new THREE.Mesh(new THREE.SphereGeometry(c.r + 1, 24, 14, 0, Math.PI * 2, 0, Math.PI / 0.62), caveMat);
  dome.position.set(c.x, c.y + 0.2, c.z);
  g.add(dome);
  const wall = new THREE.Mesh(new THREE.CylinderGeometry(c.r + 1, c.r + 1, 5.4, 24, 1, true), caveMat);
  wall.position.set(c.x, c.y + 2.7, c.z);
  g.add(wall);
  c.dome = dome;
  // soft wall ring so the player cannot walk through the cave walls
  const n = 12;
  for (let k = 0; k < n; k++) {
    const a = (k / n) * Math.PI * 2;
    c.colliders.push({ x: c.x + Math.cos(a) * (c.r - 0.2), z: c.z + Math.sin(a) * (c.r - 0.2), r: 1.7, minY: c.y - 1, maxY: c.y + 5 });
  }
  // Unopened caves do not reserve lights or illuminate the surface.
  c.light = null;
  // Survey mine portals make bounded caves accessible without abusing a heightfield as a tunnel.
  if(CFG.terrainVersion===2){
    c.entranceY=baseHeight(c.entranceX,c.entranceZ);
    if(c.entranceY<CFG.waterLevel+1){c.entranceX=c.x;c.entranceZ=c.z;c.entranceY=baseHeight(c.x,c.z);}
    const portal=new THREE.Group();portal.position.set(c.entranceX,c.entranceY,c.entranceZ);
    for(const [x,y,w,h]of [[-1.3,1.15,.65,2.8],[1.3,1.15,.65,2.8],[0,2.5,3.2,.55]]){
      const rock=ART.instance('rockB',h);if(rock){rock.position.set(x,y-h/2,0);rock.scale.x=w/h*1.6;portal.add(rock);}
    }
    const entranceMat=new THREE.MeshStandardMaterial({color:0x151918,roughness:1});
    const dark=new THREE.Mesh(new THREE.PlaneGeometry(2.1,2.4),entranceMat);dark.position.set(0,1.2,.1);portal.add(dark);
    const beam=new THREE.Mesh(new THREE.BoxGeometry(2.8,.15,.18),MAT.trunk);beam.position.set(0,2.45,.2);portal.add(beam);
    for(const x of [-1.14,1.14]){const support=new THREE.Mesh(new THREE.BoxGeometry(.15,2.4,.18),MAT.trunk);support.position.set(x,1.2,.2);portal.add(support);}
    c.colliders.push({x:c.entranceX,z:c.entranceZ+.35,r:1.35,minY:c.entranceY-.5,maxY:c.entranceY+3});
    const signCanvas=document.createElement('canvas');signCanvas.width=256;signCanvas.height=96;const ctx=signCanvas.getContext('2d');ctx.fillStyle='#302c23';ctx.fillRect(0,0,256,96);ctx.fillStyle='#cbbb92';ctx.font='bold 23px monospace';ctx.fillText('SURVEY MINE',28,40);ctx.font='16px monospace';ctx.fillText('IRON / KEEP A LIGHT',22,70);
    const sign=new THREE.Mesh(new THREE.PlaneGeometry(1.3,.49),new THREE.MeshStandardMaterial({map:new THREE.CanvasTexture(signCanvas),roughness:1}));sign.position.set(0,2.9,.21);portal.add(sign);g.add(portal);c.portal=portal;
    const ladder=new THREE.Group();for(const x of [-.45,.45]){const rail=new THREE.Mesh(new THREE.BoxGeometry(.09,3,.09),MAT.trunk);rail.position.set(x,1.5,0);ladder.add(rail);}for(let i=0;i<9;i++){const rung=new THREE.Mesh(new THREE.BoxGeometry(.95,.07,.09),MAT.trunk);rung.position.y=.3+i*.3;ladder.add(rung);}ladder.position.set(c.x,c.y-.2,c.z-c.r+3);g.add(ladder);c.exit=ladder.position.clone();
    for(let i=0;i<10;i++){const a=i*Math.PI*.2,rr=c.r*.68;const formation=ART.instance('rockB',1+(i%3)*.6);if(formation){formation.position.set(c.x+Math.cos(a)*rr,c.y-.4,c.z+Math.sin(a)*rr);g.add(formation);c.colliders.push({x:formation.position.x,z:formation.position.z,r:.7,minY:c.y-1,maxY:c.y+2.6});}}
    const marking=new THREE.Mesh(new THREE.PlaneGeometry(1,.8),new THREE.MeshStandardMaterial({color:0xae8b60,roughness:1}));marking.position.set(c.x+1.6,c.y+1.4,c.z-c.r+.5);g.add(marking);
  }
  // rich ore veins on the cave floor
  const rng = mulberry32((c.i * 7919) ^ (c.j * 104729) ^ CFG.seed);
  const oreN = 3 + Math.floor(rng() * 2);
  for (let k = 0; k < oreN; k++) {
    const a = rng() * Math.PI * 2, rr = rng() * (c.r - 2.5);
    const ox2 = c.x + Math.cos(a) * rr, oz2 = c.z + Math.sin(a) * rr;
    const key = hkey(ox2, oz2);
    const kind = rng() < 0.55 ? 'iron' : 'gold';
    if (world.oreTaken.has(key)) continue;
    const node = makeOreNode(kind);
    node.position.set(ox2, c.y + 0.2, oz2);
    g.add(node);
    const id=`${CFG.seed}:cave:${c.i},${c.j}:${key}`,saved=world.harvestState.get(id);
    c.harvest.push({ id,hp:saved?.hp??15, x: ox2, z: oz2, y: c.y + 0.2, r: 1.3, maxHp: 15, type: 'ore', oreKind: kind, hidden: false, group: node, shake: 0, dead: false });
  }
  c.meshGroup = g;
  scene.add(g);
}
function nearbyCaveEntrance(){
  return world.caves.find(c=>c.portal&&((player.pos.y>c.y+5&&dist2D(player.pos.x,player.pos.z,c.entranceX,c.entranceZ)<4)|| (player.pos.y<c.y+5&&dist2D(player.pos.x,player.pos.z,c.exit.x,c.exit.z)<3)));
}
function caveEntranceText(){const c=nearbyCaveEntrance();return c?player.pos.y>c.y+5?'[ E ] DESCEND SURVEY MINE · BRING A TORCH':'[ E ] CLIMB TO THE SURFACE':'';}
function useCaveEntrance(){
  const c=nearbyCaveEntrance();if(!c)return false;
  const enter=player.pos.y>c.y+5;
  player.pos.set(enter?c.exit.x:c.entranceX,enter?c.y:c.entranceY,enter?c.exit.z+1.5:c.entranceZ-2.3);
  player.vel.set(0,0,0);resolveCollision(player.pos,player.radius);camera.position.set(player.pos.x,player.pos.y+CFG.playerHeight,player.pos.z);
  showToast(enter?'Survey chamber · exposed iron, gilded veins and crawl tracks':'Back beneath the open sky',2200);AudioFX.play('lore');return true;
}
function disposeCave(c){
  for(const h of c.harvest)if(h.id)world.harvestState.set(h.id,{hp:h.hp,dead:h.dead,hidden:h.hidden});
  c.meshGroup?.removeFromParent();const mats=new Set();
  c.meshGroup?.traverse(o=>{if(o.geometry&&!SHARED_GEOMS.has(o.geometry))o.geometry.dispose();if(o.material&&![MAT.rock,MAT.trunk].includes(o.material)&&!ART.sharedMaterials.has(o.material))mats.add(o.material);});
  // Imported materials are cache-owned; dispose only chamber-local materials.
  for(const m of mats){if(m.map&&m.map!==TEX.rock)m.map.dispose();m.dispose();} 
  freeLight(c.light);
}
function updateCaveStream() {
  const px = player.pos.x, pz = player.pos.z;
  const i0 = Math.floor((px - 170) / CAVE_CELL), i1 = Math.floor((px + 170) / CAVE_CELL);
  const j0 = Math.floor((pz - 170) / CAVE_CELL), j1 = Math.floor((pz + 170) / CAVE_CELL);
  let changed = false;
  for (let i = i0; i <= i1; i++) {
    for (let j = j0; j <= j1; j++) {
      if (world.caves.some((c) => c.i === i && c.j === j)) continue;
      const site = caveSiteAt(i, j);
      if (!site || dist2D(site.x, site.z, px, pz) > 185) continue;
      buildCaveMeshes(site);
      world.caves.push(site);
      changed = true;
    }
  }
  for (let k = world.caves.length - 1; k >= 0; k--) {
    const c = world.caves[k];
    if (dist2D(c.x, c.z, px, pz) < 320) continue;
    disposeCave(c);
    world.caves.splice(k, 1);
    changed = true;
  }
  if (changed) rebuildColliders();
}
function updateCaves(dt) {
  for (const c of world.caves) {
    // breaching: dug the surface down into the chamber ceiling
    if (!c.breached) {
      const s = terrainHeight(c.x, c.z);
      const s2 = terrainHeight(c.x + c.r * 0.55, c.z) ;
      const s3 = terrainHeight(c.x, c.z + c.r * 0.55);
      if (Math.min(s, s2, s3) < c.y + 5) {
        c.breached = true;
        if (c.dome) c.dome.visible = false;
        showToast('YOU BREACHED A <b>CAVE</b>!', 3200);
        AudioFX.play('boss');
      }
    }
    const nearCave = c.breached && Math.abs(player.pos.y - c.y) < 7 && dist2D(player.pos.x, player.pos.z, c.x, c.z) < c.r + 5;
    if(nearCave&&!c.light){for(const t of world.torches)if(t.light&&t.group.position.distanceTo(camera.position)>26){freeLight(t.light);t.light=null;}}
    if (nearCave && !c.light) { c.light = allocLight(0xffb26a, 1.1, 18, 0.15); if (c.light) c.light.light.position.set(c.x, c.y + 3, c.z); }
    if (!nearCave && c.light) { freeLight(c.light); c.light = null; }
    // crawlers wake when the player is near an open cave
    if (c.breached) {
      const d = dist2D(player.pos.x, player.pos.z, c.x, c.z);
      if (d < 40 && Math.abs(player.pos.y-c.y)<7) {
        c.mobTimer -= dt;
        if (c.mobTimer <= 0) {
          c.mobTimer = 7 + Math.random() * 8;
          const alive = world.crawlers.filter((x) => x.alive).length;
          if (alive < 6 && c.mobs < 3) {
            const a = Math.random() * Math.PI * 2, rr = Math.random() * (c.r - 3);
            spawnCrawler(c.x + Math.cos(a) * rr, c.y, c.z + Math.sin(a) * rr);
            c.mobs++;
          }
        }
      }
    }
  }
}

// ---- cave crawlers (fast, aggressive, guard the deep ore) ----
function buildCrawler() {
  const group = new THREE.Group();
  const mat = new THREE.MeshStandardMaterial({ map:TEX.rock, color: 0x544c40, roughness: .93, metalness: .05 });
  const body = new THREE.Mesh(new THREE.SphereGeometry(0.55, 18, 14), mat);
  body.position.y = 0.82;
  body.scale.set(1.15, 0.72, 1.35);
  group.add(body);
  const head = new THREE.Mesh(new THREE.SphereGeometry(0.33, 16, 12), mat);
  head.position.set(0, 0.88, 0.86);
  group.add(head);
  const eyeMat = new THREE.MeshStandardMaterial({ color: 0xff5533, emissive: 0xff3311, emissiveIntensity: 2.4 });
  for (const s of [-1, 1]) {
    const e = new THREE.Mesh(new THREE.SphereGeometry(0.085, 10, 8), eyeMat);
    e.position.set(s * 0.15, 0.98, 1.13);
    group.add(e);
  }
  const legs = [];
  for (let i = 0; i < 6; i++) {
    const side = i % 2 === 0 ? -1 : 1;
    const fz = 0.72 - Math.floor(i / 2) * 0.72;
    const pivot = new THREE.Group();
    pivot.position.set(side * 0.52, 0.78, fz);
    const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.055, 0.035, 1.1, 8, 3), mat);
    leg.position.set(side * 0.38, -0.3, 0);
    leg.rotation.z = side * 0.95;
    pivot.add(leg);
    group.add(pivot);
    legs.push(pivot);
  }
  // Layered chitin, jointed legs and pale mandibles replace the smooth toy-spider silhouette.
  const shell=new THREE.MeshStandardMaterial({map:TEX.bark,color:0x6c6250,roughness:.92});
  const bone=new THREE.MeshStandardMaterial({color:0xa19378,roughness:.95});
  for(let i=0;i<4;i++){const plate=new THREE.Mesh(new THREE.IcosahedronGeometry(.45,0),shell);plate.scale.set(1.2,.42,.7);plate.position.set(0,1.08, -.6+i*.35);group.add(plate);}
  for(const side of [-1,1]){const fang=new THREE.Mesh(new THREE.ConeGeometry(.085,.43,6),bone);fang.rotation.set(.65,0,side*.4);fang.position.set(side*.18,.65,1.12);group.add(fang);}
  for(let i=0;i<legs.length;i++){const side=i%2===0?-1:1;const joint=new THREE.Mesh(new THREE.SphereGeometry(.09,8,6),shell);joint.position.set(side*.67,-.16,0);legs[i].add(joint);const tip=new THREE.Mesh(new THREE.ConeGeometry(.045,.5,6),bone);tip.position.set(side*.82,-.48,0);tip.rotation.z=side*.3;legs[i].add(tip);}
  return { group, legs, mats: [mat,shell,bone,eyeMat] };
}
function spawnCrawler(x, y, z) {
  const built = buildCrawler();
  built.group.position.set(x, y, z);
  scene.add(built.group);
  world.crawlers.push({ ...built, hp: 8, speed: 5.6, dir: Math.random() * Math.PI * 2,
    walkPhase: Math.random() * 6, alive: true, deathT: 0, attackCooldown: 0, turnT: 2 });
}
function updateCrawlers(dt) {
  if (state.paused) return;
  const p = player.pos;
  for (let i = world.crawlers.length - 1; i >= 0; i--) {
    const cr = world.crawlers[i];
    if (!cr.alive) {
      if(deathSystem.updateDeath(cr,dt))world.crawlers.splice(i,1);
      continue;
    }
    const dx = p.x - cr.group.position.x, dz = p.z - cr.group.position.z;
    const d = Math.hypot(dx, dz);
    let speed = 0;
    if (d < 16) {
      cr.dir = Math.atan2(dx, dz);        // chase aggressively
      speed = d > 1.3 ? cr.speed : 0;
    } else {
      cr.turnT -= dt;
      speed = 1.5;
      if (cr.turnT <= 0) { cr.turnT = 2 + Math.random() * 3; cr.dir += (Math.random() - 0.5) * 2.4; }
    }
    cr.stun = Math.max(0, (cr.stun || 0) - dt);
    if (cr.stun || cr.windup) speed = 0;
    cr.group.position.x += Math.sin(cr.dir) * speed * dt;
    cr.group.position.z += Math.cos(cr.dir) * speed * dt;
    resolveCollision(cr.group.position,.42);resolveBuildCollision(cr.group.position,.42);
    cr.group.position.y = groundHeightAt(cr.group.position.x, cr.group.position.z, cr.group.position.y);
    cr.group.rotation.y = cr.dir;
    cr.walkPhase += dt * speed * 2.2;
    for (let li = 0; li < cr.legs.length; li++) {
      cr.legs[li].rotation.x = speed > 0.1 ? Math.sin(cr.walkPhase + li * 1.9) * 0.55 : 0;
    }
    cr.attackCooldown -= dt;
    if (Math.abs(p.y-cr.group.position.y)<2.5 && d < 2.7 && cr.attackCooldown <= 0 && !cr.stun && !cr.windup) { cr.windup = 0.3; cr.attackCooldown = 1.5; AudioFX.play('mob'); }
    if (cr.windup > 0) {
      cr.windup -= dt;
      cr.group.scale.y = 0.75;
      if (cr.windup <= 0 && d < 2.5 && Math.abs(p.y-cr.group.position.y)<2.5) {
      damagePlayer(10, 'A CAVE CRAWLER GOT YOU');
      player.vel.x += (dx / (d || 1)) * -3.4;
      player.vel.z += (dz / (d || 1)) * -3.4;
      }
    } else cr.group.scale.y = 1;

  }
}
function hurtCrawler(cr, dmg) {
  if (!cr.alive) return;
  cr.hp -= dmg;
  impactFeedback(cr); cr.stun = 0.35; cr.windup = 0;
  const dx = cr.group.position.x - player.pos.x, dz = cr.group.position.z - player.pos.z;
  const d = Math.hypot(dx, dz) || 1;
  cr.group.position.x += (dx / d) * 1.0;
  cr.group.position.z += (dz / d) * 1.0;
  AudioFX.play('mob');
  if (cr.hp <= 0) {
    deathSystem.beginDeath(cr,'crawler',{iron:2,fiber:1});
  }
}

// ---- husk spawner (night only) ----
let huskTimer = 3;
function updateHuskSpawner(dt) {
  if (!state.started || state.dead || state.paused) return;
  huskTimer -= dt;
  const alive = world.husks.filter((e) => e.alive).length;
  if (huskTimer <= 0) {
    huskTimer = Math.max(10, 30 - state.days * 4) + Math.random() * 8;
    const cap = state.night ? Math.min(7, 1 + state.days * 2) : 0;
    if (alive < cap) {
      const a = Math.random() * Math.PI * 2, r = 26 + Math.random() * 16;
      const x = player.pos.x + Math.cos(a) * r, z = player.pos.z + Math.sin(a) * r;
      if (!waterColumnAt(x, z)) spawnHusk(x, z);
    }
  }
}

// ---- per-frame update (exposed for deterministic testing) ----
let heartTimer = 0, caveStreamTimer = 0;
function updateAll(dt) {
  updateFeedback(dt);
  inventoryUI.tick(dt);
  if(AudioFX.ambientGain&&AudioFX.ctx)AudioFX.ambientGain.gain.setTargetAtTime((state.paused||state.dead) ? .008 : (state.night ? .05 : .025),AudioFX.ctx.currentTime,.4);
  if (!state.started || state.dead) { if(state.dead)deathSystem.updatePlayerDeath(dt);shovelPreview.visible=false;syncCursor(); return; }
  if (state.paused) { shovelPreview.visible=false;syncCursor();return; } // full freeze under menus
  state.time += dt;
  // day counter: tick over at dawn (cycle phase wrap)
  const prevPhase = state.cyclePhase;
  updateCycle(dt);
  if (state.cyclePhase < prevPhase) {
    state.days++;
    showToast('DAY <b>' + (state.days + 1) + '</b> BEGINS', 2600);
  }
  updateWeather(dt);
  ranged.tick(dt);
  updatePlayer(dt);
  updateBreath(dt);if(state.dead)return;
  updateHunger(dt);if(state.dead)return;
  updateChunks(player.pos.x, player.pos.z);
  updateHarvest(dt);
  updateOreNodes();
  caveStreamTimer -= dt;
  if (caveStreamTimer <= 0) { caveStreamTimer = 1; updateCaveStream(); }
  updateCaves(dt);
  updateCrawlers(dt);
  updateLightFlicker();
  updateMobs(dt);
  updateMobSpawner(dt);
  updateTomPearl(dt);
  updateTomEffects(dt);
  checkBossAwaken();
  updateHusks(dt);
  updateHuskSpawner(dt);
  updateCamp(dt);
  updateBursts(dt);
  updateInteractionPrompt(); updateShovelPreview();
  updateWeatherParticles(dt);
  updateClouds(dt);
  updateMotes(dt);
  updateGodRays();
  TEX.waterN.offset.x = (state.time * 0.012) % 1;   // scrolling ripple normals
  TEX.waterN.offset.y = (state.time * 0.008) % 1;
  state.toolCooldown = Math.max(0, state.toolCooldown - dt);
  // tool swing animation
  if (toolSwing > 0) {
    const w=activeWeapon();toolSwing = Math.max(0, toolSwing - dt / w.cooldown);
    const k = Math.sin((1 - toolSwing) * Math.PI);
    const motions={jab:[.2,.1,.05],bash:[1.4,.25,.35],chop:[1.1,.15,.8],mine:[1.4,.1,.2],slash:[.35,1.2,1.1],cleave:[1.5,.5,.5],scoop:[.85,.2,.25]};
    const [x,y,z]=motions[w.motion];toolView.rotation.set(-.35-k*x,.2-k*y,.15+k*z);
    toolView.position.z=-.95-(w.motion==='jab'?k*.24:0);
    if(toolSwing===0){toolView.rotation.set(-.35,.2,.15);toolView.position.z=-.95;}
  }
  // lightning flash decay
  state.flash = Math.max(0, state.flash - dt * 3.4);
  dom.lightning.style.opacity = String(state.flash * 0.85);
  // follow world objects
  sky.position.copy(camera.position);
  stars.position.copy(camera.position);
  playerLight.position.set(player.pos.x, player.pos.y + 1.6, player.pos.z);
  // held torch light follows the camera when the torch is selected
  if (heldLight) {
    const holding = activeWeapon() && activeWeapon().torch && state.crafted.has('torch');
    heldLight.base = holding ? 1.9 : 0;
    heldLight.light.position.copy(camera.position);
  }
  // heartbeat when Tom Pearl is near
  if (state.danger > 0.3 && state.started && !state.dead && !state.paused) {
    heartTimer -= dt;
    if (heartTimer <= 0) { AudioFX.play('heart'); heartTimer = lerp(1.15, 0.42, clamp(state.danger, 0, 1)); }
  }
  hudTimer -= dt;
  if (hudTimer <= 0) { hudTimer = 0.12; updateHUD(); drawMinimap(); updateCampHUD(); }
}
let hudTimer = 0;

// ---- main loop ----
let _last = performance.now();
function animate() {
  if (new URLSearchParams(location.search).get('qa') !== 'manual') requestAnimationFrame(animate);
  const now = performance.now();
  let dt = (now - _last) / 1000; _last = now;
  dt = Math.min(dt, 0.05);
  updateAll(dt);
  // Paused/menu scenes need no continuous expensive redraws.
  if (state.paused || (state.dead&&deathSystem.playerDeath.done) || !state.started) {
    if (now - (animate.lastMenuRender || 0) < 200) return;
    animate.lastMenuRender = now;
  }
  if (Q.bloom) composer.render();
  else renderer.render(scene, camera);
}

// ---- input bindings ----
window.addEventListener('keydown', (e) => {
  if (!state.started || state.dead) return;
  if(e.target instanceof HTMLElement && (e.target.matches('input,textarea,select')||e.target.isContentEditable))return;
  if (e.repeat) return;
  // Escape in a focused browser can arrive before pointerlockchange.
  if (e.code === 'Escape' && document.pointerLockElement === renderer.domElement) { document.exitPointerLock(); return; }
  AudioFX.resume();
  input.keys.add(e.code);
  refreshInput();
  if (e.code === 'KeyE' && playable()) swingWeapon();
  if (e.code === 'KeyB') toggleBuild();
  if (e.code === 'KeyR' && playable() && build.mode) { build.rotation = (build.rotation+1)%4; updateBuildPreview(); }
  if (e.code === 'KeyX' && playable()) {if(!dismantleTorch())dismantleStructure();}
  if (e.code === 'KeyJ' && playable()) openJournal();
  if (e.code === 'KeyI') { e.preventDefault(); toggleInventory(); }
  if (e.code === 'KeyC') {
    if (!dom.craft.classList.contains('hidden')) closeCraft();
    else openCraft();
  }
  if (e.code === 'KeyQ' && playable()) selectSlot((state.sel + 1) % 9);
  if (e.code === 'KeyV' && playable()) fillGround(pickDigPoint());

  if (e.code === 'KeyF') eatFood();
  if (e.code.startsWith('Digit') && playable()) {      const n = parseInt(e.code.slice(5), 10);
    if(n>=1&&n<=9)selectSlot(n-1);
  }
  if (e.code === 'Escape') {
    // Pointer-lock escape is handled by pointerlockchange; do not immediately relock.
    if (!input.pointerLocked && performance.now() - input.unlockedAt > 250) togglePause();
  }
  if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.code)) e.preventDefault();
});
window.addEventListener('wheel', (e) => {
  if (!state.started || state.dead || state.paused) return;
  if (build.mode) { chooseBuild((build.index+(e.deltaY>0?1:-1)+BUILD_PARTS.length)%BUILD_PARTS.length); return; }
  selectSlot((state.sel + (e.deltaY > 0 ? 1 : -1) + 9) % 9);
}, { passive: true });
window.addEventListener('keyup', (e) => {
  input.keys.delete(e.code);
  refreshInput();
});
renderer.domElement.addEventListener('mousedown', (e) => {
  if (!playable()) return;
  AudioFX.resume();
  if (!input.pointerLocked) {
    input.dragging = true; input.lastX = e.clientX; input.lastY = e.clientY;
    syncCursor();
    if (e.button === 0) lockPointer();
    return; // capture click never also strikes or places a structure
  }
  if (e.button === 0) swingWeapon();
  if (e.button === 2 && activeWeapon().shovel) fillGround(pickDigPoint());
});
renderer.domElement.addEventListener('contextmenu', e => e.preventDefault());
document.addEventListener('pointerlockchange', () => {
  const wasLocked = input.pointerLocked;
  input.pending = false; input.dragging = false; syncCursor();
  if (input.pointerLocked && !playable()) { document.exitPointerLock(); return; }
  if (wasLocked && !input.pointerLocked) {
    input.unlockedAt = performance.now();
    if (playable()) openPause();
  }
});
document.addEventListener('pointerlockerror', () => {
  input.pending = false; syncCursor();
  if (playable()) showToast('Mouse capture unavailable · hold RIGHT mouse to look · <b>E</b> to use', 3500);
});
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  composer.setSize(window.innerWidth, window.innerHeight);
});

// ---- pause menu ----
function lockPointer() {
  syncCursor();
  if (!playable() || input.pointerLocked || input.pending || !renderer.domElement.requestPointerLock) return;
  input.pending = true; input.requestedAt = performance.now();
  const id = ++input.requestId;
  const fail = () => { if (id === input.requestId) { input.pending = false; syncCursor(); } };
  try { const p = renderer.domElement.requestPointerLock(); if (p && p.catch) p.catch(fail); }
  catch (err) { fail(); showToast('Hold RIGHT mouse to look · <b>E</b> to use', 3000); }
}
function openPause() {
  if (!state.started || state.dead || state.paused) return;
  state.paused = true;
  dom.pause.classList.remove('hidden');
  dom.pause.classList.add('fade-in');
  AudioFX.setUnderwater(false);
  releaseInput();
  resetFeedback();
}
function closePause() {
  dom.pause.classList.add('hidden');
  if (state.dead || !state.started) return;
  state.paused = false;
  AudioFX.resume();
  lockPointer();
  syncCursor();
}
function togglePause() {
  if (closeCampOverlay()) return;
  if (build.mode) { cancelBuild(); return; }
  if (!dom.craft.classList.contains('hidden')) { closeCraft(); return; }   // Esc closes crafting
  if (!dom.pause.classList.contains('hidden')) closePause();
  else openPause();
}

// ---- variable graphics quality ----
function applyQuality(name, rebuild = true) {
  const preset = QUALITY_PRESETS[name];
  state.quality = preset ? name : 'high';
  Object.assign(Q, preset || QUALITY_PRESETS.high);
  try { localStorage.setItem('wildwood-quality', state.quality); } catch (e) { /* ignore */ }
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, Q.pixelRatio));
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.shadowMap.enabled = Q.shadows;
  sunLight.castShadow = Q.shadows;
  if (sunLight.shadow.mapSize.x !== Q.shadowSize) {
    sunLight.shadow.mapSize.set(Q.shadowSize, Q.shadowSize);
    if (sunLight.shadow.map) { sunLight.shadow.map.dispose(); sunLight.shadow.map = null; }
  }
  bloomPass.strength = Q.bloomStrength;
  composer.setSize(window.innerWidth, window.innerHeight);
  // Keep every gameplay object and collider. Only terrain tessellation/presentation changes.
  if (rebuild) for (const chunk of world.chunks.values()) {
    if (chunk.terrainMesh.geometry.parameters.widthSegments !== Q.terrainSeg) {
      const geo = new THREE.PlaneGeometry(CFG.chunkSize,CFG.chunkSize,Q.terrainSeg,Q.terrainSeg);
      geo.rotateX(-Math.PI/2); geo.translate(CFG.chunkSize/2,0,CFG.chunkSize/2);
      const p=geo.attributes.position,u=geo.attributes.uv;
      for(let i=0;i<p.count;i++)u.setXY(i,(chunk.cx*CFG.chunkSize+p.getX(i))*.35,(chunk.cz*CFG.chunkSize+p.getZ(i))*.35);
      geo.setAttribute('color',new THREE.BufferAttribute(new Float32Array(p.count*3),3));
      chunk.terrainMesh.geometry.dispose(); chunk.terrainMesh.geometry=geo; remeshChunk(chunk.cx,chunk.cz);
    }
    applyChunkVisuals(chunk);
  }
  for (const b of document.querySelectorAll('[data-quality]')) {
    b.classList.toggle('active', b.getAttribute('data-quality') === state.quality);
  }
}

for (const b of document.querySelectorAll('[data-quality]')) {
  b.addEventListener('click', () => {
    applyQuality(b.getAttribute('data-quality'));
    AudioFX.play('lore');
  });
}

// ---- start / restart ----
function startGame() {
  if (state.started) return;
  items.reset(); state.staminaWait=0;
  state.started = true;
  initCamp();
  for(const [id,dx,dz,n]of [['wood',1,-3,6],['stone',-1,-3,3],['fiber',2,-4,3],['berries',-2,-4,3]])ranged.addLoot(id,n,new THREE.Vector3(player.pos.x+dx,player.pos.y,player.pos.z+dz));
  dom.story.classList.add('hidden');
  AudioFX.init(); AudioFX.resume();
  lockPointer();
}
function disposeEntity(entity) {
  ART.cleanup(entity);
  entity.group.removeFromParent();
  const geometries = new Set(), materials = new Set();
  entity.group.traverse(o => { if (o.geometry) geometries.add(o.geometry);if(o.material)for(const m of Array.isArray(o.material)?o.material:[o.material])if(!ART.sharedMaterials.has(m)&&!Object.values(MAT).includes(m))materials.add(m); });
  for (const geometry of geometries) if (!SHARED_GEOMS.has(geometry)) geometry.dispose();
  for (const material of entity.mats || []) materials.add(material);
  for(const mat of feedback.impacts.keys())if(materials.has(mat))feedback.impacts.delete(mat);
  for (const material of materials) material.dispose();
}
function clearEntities() {
  inventoryUI.closePreview();ranged.reset();
  for (const e of world.husks) disposeEntity(e);
  for (const m of world.mobs) disposeEntity(m);
  for (const cr of world.crawlers) disposeEntity(cr);
  for (const t of [...world.torches]) removeTorch(t);
  for (const c of world.caves) disposeCave(c);
  for (const b of world.bursts) { scene.remove(b.pts); b.pts.geometry.dispose(); b.pts.material.dispose(); }
  world.husks.length = 0;
  world.mobs.length = 0;
  world.crawlers.length = 0;
  world.torches.length = 0;
  world.caves.length = 0;
  world.bursts.length = 0;
  if (world.tomPearl) { disposeEntity(world.tomPearl); world.tomPearl = null; }
}
let resetAt = -1000;
function resetGame() {
  if (performance.now() - resetAt < 1000) return;
  resetAt = performance.now();
  releaseInput(); resetFeedback(); clearCamp(); clearEntities();
  world.digs.length = 0; world.digCells.clear();
  world.chopped.clear(); world.oreTaken.clear(); world.oreShown.clear(); world.harvestState.clear();
  for (const key of Array.from(world.chunks.keys())) unloadChunk(key);
  world.harvestState.clear();
  // New runs use enhanced landforms; migrated camps retain their original base terrain.
  CFG.terrainVersion=2;
  // reset player
  const sp = findSpawn();
  player.pos.copy(sp);
  player.vel.set(0, 0, 0);
  player.yaw = 0; player.pitch = -0.08; player.bob = 0; player._lastStep = 0; player.onGround = true;
  camera.position.set(sp.x, sp.y + EYE, sp.z); camera.rotation.set(player.pitch, 0, 0, 'YXZ');
  state.time = 0; state.night = false; toolSwing = 0; heartTimer = 0; caveStreamTimer = 0; mobTimer = 5; huskTimer = 20;
  Object.assign(weather, { type: 'clear', next: 'clear', intensity: 0, timer: 100, lightningTimer: 5 });
  AudioFX.setUnderwater(false); if (AudioFX.lastSounds) AudioFX.lastSounds.clear();
  // reset state
  state.hp = 100; state.stamina = 100;
  state.hunger = 100; state.breath = 100; state.drownT = 0;
  items.reset(); state.staminaWait=0;
  state.sel = 0;
  state.dead = false; state.paused = false;
  state.toolCooldown = 0;
  state.days = 0; state.lastTomDay = -1;
  state.cyclePhase = 0.22;
  dom.death.classList.add('hidden');
  dom.craft.classList.add('hidden');
  dom.pause.classList.add('hidden');
  $('inventory-overlay').classList.add('hidden');
  dom.damageFlash.style.opacity = '0';
  dom.dangerVignette.style.opacity = '0';
  world.digs.length = 0;
  world.digCells.clear();
  world.chopped.clear();
  world.oreTaken.clear();
  world.oreShown.clear();
  world.caves.length = 0;
  world.crawlers.length = 0;
  world.torches.length = 0;
  for (const key of Array.from(world.chunks.keys())) unloadChunk(key);
  updateChunks(player.pos.x, player.pos.z);
  updateHotbar(); updateToolView();
  state.started = true;
  AudioFX.init(); AudioFX.resume();
  lockPointer();
  resolveCollision(player.pos, 1.2); player.pos.y = terrainHeight(player.pos.x, player.pos.z);
  camera.position.set(player.pos.x, player.pos.y + EYE, player.pos.z);
  initCamp();
  for(const [id,dx,dz,n]of [['wood',1,-3,6],['stone',-1,-3,3],['fiber',2,-4,3],['berries',-2,-4,3]])ranged.addLoot(id,n,new THREE.Vector3(player.pos.x+dx,player.pos.y,player.pos.z+dz));
  showToast('A NEW <b>DAY ONE</b> · Follow the amber camp marker', 3500);
}

$('start-button').addEventListener('click', startGame);
$('restart-button').addEventListener('click', resetGame);
$('craft-close').addEventListener('click', closeCraft);
$('inventory-close').addEventListener('click', closeInventory);
$('resume-button').addEventListener('click', closePause);
$('pause-restart-button').addEventListener('click', resetGame);

// ---- spawn search: start on dry, walkable ground near the origin ----
function findSpawn() {
  let safeFallback = null;
  for (let r = 0; r < 240; r += 3) {
    for (let a = 0; a < 16; a++) {
      const ang = (a / 16) * Math.PI * 2;
      const x = Math.cos(ang) * r, z = Math.sin(ang) * r;
      const h = terrainHeight(x, z);
      const slope = Math.max(...[[1,0],[-1,0],[0,1],[0,-1]].map(([dx,dz]) => Math.abs(terrainHeight(x+dx*2,z+dz*2)-h)));
      if (h > CFG.waterLevel + 1.5 && h < 14 && slope < 0.65) {
        const spot = new THREE.Vector3(x, h, z);
        safeFallback ||= spot;
        const biome = biomeAt(x, z, h);
        if (h > 0.5 && (biome === 'forest' || biome === 'plains')) return spot;
      }
    }
  }
  return safeFallback || new THREE.Vector3(0, Math.max(terrainHeight(0, 0), CFG.waterLevel + 2), 0);
}

const inventoryUI=installInventoryUI({THREE,ART,items,state,selectSlot,updateToolView,AudioFX,TEX,showToast});
items.onChange(()=>{updateHotbar();updateToolView();});
const ranged=installCombat({THREE,ART,items,state,world,player,camera,scene,CFG,toolView,terrainHeight,groundHeightAt,AudioFX,showToast,spawnBurst,flashHitmarker,disposeEntity,
  TEX,feedback,activeWeapon,spawnMob,spawnHusk,spawnCrawler,spawnTomPearl,
  save:()=>survival.saveGame(false),
  hitEnemy:(e,n)=>e===world.tomPearl?hurtTomPearl(n):world.mobs.includes(e)?hurtMob(e,n):world.husks.includes(e)?hurtHusk(e,n):hurtCrawler(e,n)
});
const deathSystem=ranged;
const survival = installSurvival({ serializePhysical:ranged.serialize,restorePhysical:ranged.restore, THREE, ART, items, activeWeapon, inventoryUI, state, world, player, camera, scene, CFG, TEX, MAT, AudioFX, dom, weather, WEAPONS, hash2, baseHeight, terrainHeight, groundHeightAt, waterColumnAt, dist2D, clamp, showToast, releaseInput, lockPointer, resetFeedback, spawnBurst, allocLight, freeLight, spawnHusk, openCraft, renderCraftList, clearEntities, unloadChunk, updateChunks, updateCaveStream, addDig, placeTorch, resolveCollision, updateHotbar, updateToolView,
  hitEnemy: (enemy, damage) => enemy === world.tomPearl ? hurtTomPearl(damage) : world.husks.includes(enemy) ? hurtHusk(enemy, damage) : hurtCrawler(enemy, damage)
});
const { build, BUILD_PARTS, nearStructure, toggleBuild, chooseBuild, cancelBuild, confirmBuild, updateBuildPreview, resolveBuildCollision, dismantleStructure, useWorldObject, openJournal, closeCampOverlay, clearCamp, initCamp, updateCamp, updateCampHUD } = survival;

// ---- boot / init ----
function init() {
  for (const geo of ART.sharedGeometry) SHARED_GEOMS.add(geo);
  let saved = null;
  try { saved = localStorage.getItem('wildwood-quality'); } catch (e) { /* ignore */ }
  applyQuality(saved || 'high', false);
  for(const [id,key]of [['res-wood','wood'],['res-stone','stone'],['res-gold','gold'],['res-iron','iron'],['res-berries','berries'],['res-meat','meat'],['res-soil','soil']]){const span=$(id);const img=document.createElement('img');img.className='item-icon';img.src=iconPath(key);img.alt=items.defs[key].name;span.before(img);}
  buildHotbar();
  updateToolView();
  // survival start: no Tom Pearl on the map — he walks only after the second night
  const sp = findSpawn();
  player.pos.copy(sp);
  updateChunks(sp.x, sp.z);
  resolveCollision(player.pos, 1.2); player.pos.y = terrainHeight(player.pos.x, player.pos.z);
  camera.position.set(player.pos.x, player.pos.y + EYE, player.pos.z);
  camera.rotation.set(player.pitch, player.yaw, 0, 'YXZ');
  updateCycle(0);
  updateHUD();
  drawMinimap();
  animate();
  setTimeout(() => dom.boot.classList.add('hidden'), 350);
}
if (new URLSearchParams(location.search).has('qa')) window.gameQA = { items, inventoryUI, activeWeapon, ranged, deathSystem, updateHUD, damageHarvest, toggleInventory, ART, WEAPONS, toolView, renderInventory, digGround, fillGround, terrainEditReason, pickDigPoint, remeshNear, remeshChunk, updateChunks, unloadChunk, aimedTorch, dismantleTorch, removeTorch, LIGHT_POOL, state, world, player, input, camera, renderer, CFG, feedback, AudioFX, startGame, resetGame, openPause, closePause, openCraft, closeCraft, swingWeapon, spawnMob, spawnHusk, spawnCrawler, spawnTomPearl, updateAll, updateMobs, findSpawn, findCombatTarget, findHarvestTarget, craftWeapon, selectSlot, damagePlayer, addDig, placeTorch, applyQuality, terrainHeight, groundHeightAt, biomeAt, scene, updateFeedback, updatePlayer, updateHuskSpawner, updateCaveStream, updateCaves, updateCrawlers, updateHusks, updateTomPearl, updateHunger, eatFood, survival, updateCycle, weather, canCraft, hurtMob, hurtHusk, hurtCrawler, hurtTomPearl, resolveCollision, resolveBuildCollision, updateBreath, useCaveEntrance, nearbyCaveEntrance };
init();


